      "sk.stage.k3v": "Ahead of plan",
      "sk.stage.proj": "PROJECT CONSOLE · LIVE",
      "sk.stage.target": "Target curve",
      "sk.stage.toast": "New interested buyer · landing page · Unit B-204",
      "sk.title": "Builtly Salgskonsoll · Sales and marketing for housing projects in one place",
      "sk.x_cta": "See the Prosjekthotell",
      "sk.x_h": "Documents, BIM and the building site?",
      "sk.x_p": "The Prosjekthotell is the project's collaboration room: revision-controlled documents, BIM in the browser, tender room and site check-in — the same project, upstream.",
      "sw.prod.h2": "The products.",
      "sw.prod.maps.d": "The map and intelligence portal for real estate: cadastre, ownership, zoning, risk and value estimate for any address — with tenant and plot radar. Norway and Sweden.",
      "sw.prod.maps.h": "Property intelligence — Builtly Maps",
      "sw.prod.maps.l": "See Builtly Maps",
      "sw.prod.ms.d": "From property to decision basis: the plot from the cadastre, zoning read, complete development alternatives with areas, sun/shadow and project economics — a report for the board and the bank.",
      "sw.prod.ms.h": "Mulighetsstudie",
      "sw.prod.ms.l": "See the Mulighetsstudie",
      "sw.prod.ph.d": "The intelligent collaboration room: revision-controlled documents, BIM straight in the browser, a complete tender room, § 15 site check-in, the FDV register that takes the building into operations — and Builtly Control for product documentation and compliance on the same project.",
      "sw.prod.ph.h": "Prosjekthotell",
      "sw.prod.ph.l": "See the Prosjekthotell",
      "sw.prod.s": "Products",
      "sw.ctl.badge": "New · early access",
      "sw.ctl.cta": "Log in to Control",
      "sw.ctl.h": "Builtly Control — product documentation and compliance",
      "sw.ctl.mer": "More about Builtly Control",
      "sw.ctl.p": "The building products in the project, the documentation behind them and the requirements they must meet — DoP, SDS, EPD and O&M — in one workspace. What is missing is measured from the documents at read time, never from a flag; gaps get an owner and a deadline. As a standalone product, or activated on a project in the Project Hotel.",
      "sw.ctl.s1": "Product register",
      "sw.ctl.s2": "Requirements and deviations",
      "sw.ctl.s3": "Audit trail",
      "sw.prod.render.d": "From architect model to photorealistic images — true to the IFC model, or from an image you already have.",
      "sw.prod.render.h": "Builtly Render",
      "sw.prod.render.l": "Explore Builtly Render",
      "sw.prod.render.tag": "New",
      "sw.prod.sk.d": "Sales and marketing for the housing project in one place: interested buyers, newsletters and SMS, landing pages, ads published straight to Meta and Snapchat — and a shareable sales console measured against the target.",
      "sw.prod.sk.h": "Salgskonsoll",
      "sw.prod.sk.l": "See the Salgskonsoll",
      "sw.prod.stag": "Five products on the market — each with its own door",
