      "nav.bimViewerFull": "BIM Viewer",
      "bimv.title": "Builtly BIM Viewer · Free IFC viewer in the browser",
      "bimv.meta": "Builtly BIM Viewer — open IFC models right in the browser, free. Measure lengths and areas, analyse floor areas and residential units. The file never leaves your machine. Free for companies and private individuals.",
      "bimv.smark.label": "Builtly BIM Viewer",
      "bimv.smark.tag": "Free IFC viewer",
      "bimv.h1": "Open BIM models<br/>right in the browser.",
      "bimv.lede": "Drag an IFC file into the browser and it opens — no installation, no licence, no company registration. Measure lengths and areas, cut sections, and read floor areas and residential units out of the model. The file is parsed locally on your machine and never uploaded. Free for companies and private individuals alike.",
      "bimv.cta.open": "Open BIM Viewer — free",
      "bimv.cta.plans": "What's included",
      "bimv.cta.short": "Open BIM Viewer",
      "bimv.stage.live": "Live",
      "bimv.stage.local": "✓ Parsed locally — never uploaded",
      "bimv.stage.free": "Free in the browser",
      "bimv.chip.elements": "Elements",
      "bimv.chip.floors": "Storeys",
      "bimv.chip.bra": "Floor area",
      "bimv.chip.units": "Units",
      "bimv.chip.measure": "Measure",
      "bimv.chip.schema": "Schema",
      "bimv.tool.measure": "Measure",
      "bimv.tool.area": "Area analysis",
      "bimv.tool.units": "Units",
      "bimv.tool.section": "Sections",
      "bimv.feat.browser.label": "IFC in the browser",
      "bimv.feat.browser.h": "No installation. No licence.",
      "bimv.feat.browser.p": "Drag in an IFC file and it opens — IFC 2x3 and IFC 4, from Revit, ArchiCAD and the rest. Real project models of a hundred megabytes and more, parsed with a streaming reader built for construction-site laptops and tablets.",
      "bimv.feat.privacy.label": "Privacy by design",
      "bimv.feat.privacy.h": "The file never leaves your machine.",
      "bimv.feat.privacy.p": "The free viewer parses the model locally in your browser — nothing is uploaded, stored or logged. Open a confidential tender model without sending it anywhere. That is not a promise in a policy; it is how the viewer is built.",
      "bimv.feat.measure.label": "Measuring tools",
      "bimv.feat.measure.h": "Measure lengths and areas.",
      "bimv.feat.measure.p": "Double-click two points for a length, corner by corner for an area. Cut sections through the model, isolate load-bearing structure, and click any element for its properties.",
      "bimv.feat.area.label": "Area analysis",
      "bimv.feat.area.h": "Floor areas out of the model.",
      "bimv.feat.area.p": "Gross and net floor areas, saleable area and per-storey breakdowns — read from the model's own surfaces and slabs, with an honest plausibility check that flags scale errors and mixed layers instead of guessing.",
      "bimv.feat.units.label": "Residential units",
      "bimv.feat.units.h": "Counts units — even without spaces.",
      "bimv.feat.units.p": "Many architect exports carry no room objects at all. The viewer measures unit signals — entrance doors in party walls, confirmed by kitchens and furniture — and shows every competing signal so a wrong reading is visible, never hidden.",
      "bimv.feat.save.label": "Model library",
      "bimv.feat.save.h": "Save models when you need them.",
      "bimv.feat.save.p": "Viewing is free, always. If you want to keep models in a library and open them from any machine, storage is 199 kr per month — activated inside the viewer, invoiced by email, cancel any time.",
      "bimv.plan.free.name": "Free",
      "bimv.plan.free.f1": "Open IFC models in the browser — unlimited",
      "bimv.plan.free.f2": "Measuring tools, sections, area analysis and unit counts",
      "bimv.plan.free.f3": "Files are parsed locally and never uploaded",
      "bimv.plan.free.f4": "Register with your email — no company required",
      "bimv.plan.pro.name": "Storage",
      "bimv.plan.pro.per": "per month",
      "bimv.plan.pro.f1": "Everything in Free",
      "bimv.plan.pro.f2": "Save models to your own library",
      "bimv.plan.pro.f3": "Open your models from any machine",
      "bimv.plan.pro.f4": "Invoiced by email — cancel any time",
      "bimv.plan.pro.note": "Activated inside the viewer when you first save a model — no card, no binding period.",
      "bimv.diff.h": "Part of the Builtly platform.",
      "bimv.diff.c1": "Project hotel / CDE",
      "bimv.diff.c2": "Federated model",
      "bimv.diff.c3": "Tender rooms",
      "bimv.diff.c4": "Engineering modules",
      "bimv.diff.p": "The viewer runs on the same BIM engine as the Builtly project hotel — where every discipline model federates into one shared model, tender packages are issued with receipts, and structural, fire, acoustic and geotechnical deliverables are produced on the platform. When your team needs more than viewing, write to <a href=\"mailto:sales@builtly.ai\" style=\"color:#5EEAD4\">sales@builtly.ai</a> or <a href=\"/bli-kunde.html\" style=\"color:#5EEAD4\">become a customer</a>.",
      "maps.smark.label": "Builtly Maps",
      "maps.smark.tag": "Property intelligence",
      "maps.h2": "Every property —<br/>from map to engineering.",
      "maps.lede": "Builtly Maps brings live property data — matrikkel, ownership, regulation, risk and area — together for any address, owner or company. Built for architects, developers and real-estate teams. And because it runs on the Builtly platform, you can plug in the engineering modules and take a property straight from a map lookup to a quality-assured deliverable.",
      "maps.f1.label": "The data layer",
      "maps.f1.h": "Every property, live.",
      "maps.f1.p": "Search by address, property, owner or company. Matrikkel, areas, BYA/BRA, title holders and corporate structure — pulled live from Kartverket and Brønnøysund. Risk layers for flood, quick clay, storm surge and ground conditions, with zoning, map layers, area analysis and case insight.",
      "maps.f2.label": "The difference",
      "maps.f2.h": "Not just data — engineering.",
      "maps.f2.p": "Where other tools stop at the data, Builtly Maps connects to the engineering modules — structural, geotechnical, fire, acoustics, climate risk and valuation. Go from a property on the map all the way to calculations, documentation and a signed deliverable, on one platform.",
      "maps.cta.open": "Open Builtly Maps",
      "maps.stage.analyzed": "✓ Analyzed",
      "maps.stage.live": "Live",
      "maps.stage.scanned": "scanned",
      "maps.stage.match": "match",
      "maps.stage.connect": "+ Engineering",
