      "maps.cta.demo": "Book a demo",
      "maps.diff.h": "Not just the data — the engineering.",
      "maps.diff.p": "Other platforms stop at the data. Because Builtly Maps runs on the Builtly engineering platform, you can take a property straight from a map lookup to structural, geotechnical, fire, acoustic, climate-risk and valuation deliverables — calculated, documented and signed. Plus a portfolio dashboard, deal pipeline, explainable leads and your own data room.",
      "maps.feat.search.label": "Search & ownership",
      "maps.feat.search.h": "Any property, any owner.",
      "maps.feat.search.p": "Search by address, property, owner or company. Live matrikkel, areas, BYA/BRA, title holders and full corporate ownership trees from Kartverket and Brønnøysund — with an open-data owner-risk indicator.",
      "maps.feat.deepdive.label": "Property deep-dive",
      "maps.feat.deepdive.h": "Everything on one property.",
      "maps.feat.deepdive.p": "Open any property to its plot, market value estimate from comparable neighbourhood sales, transaction history, owners, tenants, surrounding area and registered building cases.",
      "maps.feat.mapanalysis.label": "Map analysis",
      "maps.feat.mapanalysis.h": "Draw, measure, analyse.",
      "maps.feat.mapanalysis.p": "Toggle map layers, draw and analyse any area, and measure distances. Risk layers for flood, quick clay, storm surge and ground conditions, plus zoning — in 2D, 3D, map or aerial.",
      "maps.feat.area.label": "Area reports",
      "maps.feat.area.h": "Know the market.",
      "maps.feat.area.p": "Instant area profiles — population, demographics, housing prices versus build cost, and new-build supply with median kr/m², units and room mix. Exportable to PDF.",
      "maps.feat.tenant.label": "Tenant radar",
      "maps.feat.tenant.h": "Find tenants first.",
      "maps.feat.tenant.p": "Find companies that will soon need new premises — before competitors. Ranked on growth, industry and stage, with the reasoning behind every signal and a route to contact.",
      "maps.feat.plot.label": "Plot radar",
      "maps.feat.plot.h": "Find buildable land.",
      "maps.feat.plot.p": "Find undeveloped, buildable plots in any municipality by area, with calculated development potential (BYA) and zoning — clustered on the map and in an exportable table.",
