      "hero.h1":                 "Groundbreaking in every discipline. One project at the centre.",
      "hero.lede.body": "Builtly is not one app that does a bit of everything. It is deep professional systems — area and yield, fire, structures, sales, documentation — built with leading discipline engineers, on one model of the project from site to operations.",
      "hero.lede.tagline": "Leading discipline specialists. Groundbreaking technology. Scalable engineering delivery.",
