      // === Industries page ===
      "industries.s01.primary_tag": "Engineering consultancies",
      "industries.s01.body1.intro": "The proposition is straightforward.",
      "industries.s01.body1.bold": "Consulting engineers are the most expensive professional capacity in the building industry, and the largest share of their time goes to manual report production rather than engineering analysis.",
      "industries.s01.body1.outro": "Builtly inverts that ratio. AI handles the routine production; the engineer's time goes to the work that justifies the fee.",
      "industries.s01.body2": "The result for the consultancy: faster deliveries, more projects per senior, and senior capacity finally deployed against work that actually requires it. The result for the engineer: less paperwork, more judgment.",
      "industries.s01.meta.segment.k": "Segment",
      "industries.s01.meta.segment.v": "Primary",
      "industries.s01.meta.modules.k": "Modules used",
      "industries.s01.meta.modules.v": "All 15",
      "industries.s01.meta.delivery.k": "Delivery levels",
      "industries.s01.meta.engagement.k": "Engagement",
      "industries.s01.meta.engagement.v": "Platform licence",
      "industries.s01.pm.h4": "Modules used by consultancies",
      "industries.s01.pm.desc": "All fifteen, across three delivery tiers",
      "industries.mod.geo": "Geotechnics",
      "industries.mod.str": "Structural",
      "industries.mod.fir": "Fire safety",
      "industries.mod.aco": "Acoustics",
      "industries.mod.env": "Environmental",
      "industries.mod.ark": "Feasibility",
      "industries.mod.tdd": "Technical DD",
      "industries.mod.bid": "Bid control",
      "industries.mod.qty": "Quantities",
      "industries.mod.hse": "HSE plan",
      "industries.mod.cli": "Climate risk",
      "industries.mod.sus": "Sustainability",
      "industries.mod.tra": "Traffic",
