      "industries.aud01.head": "Real-estate developers",
      "industries.aud01.h3": "Faster feasibility. Faster diligence.",
      "industries.aud01.body": "Developers buy automated feasibility studies, technical due diligence and climate-risk reports directly. The use case is decision speed: site acquisition runs on tight timelines, and waiting weeks for a consultancy DD often loses the deal.",
      "industries.aud01.ml": "Typical modules",
      "industries.aud01.engagement.k": "Engagement",
      "industries.aud01.engagement.v": "Direct",
      "industries.aud02.h3": "Technical underwriting at portfolio scale.",
      "industries.aud02.body1": "Lenders use Builtly for the technical-credit basis behind construction loans, for ongoing construction-loan monitoring, and for portfolio-level climate risk against disclosure requirements. The volume of decisions makes manual consultancy review prohibitive.",
      "industries.aud02.body2": "The platform produces structured outputs that integrate into credit-decisioning systems and portfolio-monitoring dashboards. White-label and API options available for high-volume buyers.",
      "industries.aud02.ml": "Typical modules",
      "industries.aud02.engagement.k": "Engagement",
      "industries.aud02.engagement.v": "Direct · API · white-label",
      "industries.aud03.h3": "Portfolio screening, disclosure compliance.",
      "industries.aud03.body1": "Asset managers and institutional investors use Builtly for portfolio-level technical and climate-risk screening, sustainability-certification pre-assessments, and the structured disclosure outputs required under financial-sector climate-risk regulation.",
      "industries.aud03.body2": "The platform scales across thousands of assets without scaling expert capacity. Results are auditable and structured for downstream reporting systems.",
      "industries.aud03.ml": "Typical modules",
      "industries.aud03.engagement.k": "Engagement",
      "industries.aud03.engagement.v": "Direct · API integration",
      "industries.aud04.head": "Public sector",
      "industries.aud04.h3": "Procurement review, planning capacity.",
      "industries.aud04.body1": "Public agencies use Builtly for automated tender-document review and for capacity-augmentation on planning applications. Public-sector engineering capacity is constrained globally, and Builtly closes part of the gap without requiring net new hiring.",
      "industries.aud04.body2": "Typical engagement runs through a consultancy partner that holds the public-sector contract, with Builtly as the underlying production layer. Direct procurement supported in jurisdictions where allowed.",
      "industries.aud04.ml": "Typical modules",
      "industries.aud04.engagement.k": "Engagement",
      "industries.aud04.engagement.v": "Consultancy partner · direct",
      "industries.uc.lede": "Specific scenarios where the platform replaces or compresses work that currently takes a consultancy weeks. The pattern is consistent across segments: a decision that needs technical underpinning, a timeline that does not allow for traditional consulting, and a regulatory standard that the output must satisfy regardless.",
      "industries.uc1.h4": "Site acquisition under timeline pressure.",
      "industries.uc1.buyer": "Real-estate developer",
      "industries.uc1.outcome": "From weeks to same-day. Decision moves from inference to evidence before exclusivity expires.",
      "industries.uc1.delivery.v": "Auto + Reviewed",
      "industries.uc2.h4": "Construction-loan underwriting at portfolio scale.",
      "industries.uc2.buyer": "Bank / construction lender",
      "industries.uc2.outcome": "Volume that was uneconomic to review manually becomes routine. Risk surfaces earlier in the lending cycle.",
      "industries.uc2.delivery.v": "Auto · API",
      "industries.uc3.h4": "Portfolio climate-risk disclosure.",
      "industries.uc3.buyer": "Asset manager / institutional investor",
      "industries.uc3.outcome": "Portfolio-scale compliance without portfolio-scale consultancy fees. Audit trail intact for regulatory examination.",
      "industries.uc3.delivery.v": "Auto · API",
      "industries.uc4.h4": "Consultancy delivery velocity.",
      "industries.uc4.buyer": "Engineering consultancy",
      "industries.uc4.outcome": "Senior engineer time spent on engineering judgment, not on report formatting. Throughput increases without staffing expansion.",
      "industries.uc4.delivery.v": "Attested",
      "industries.uc5.h4": "Public tender preparation under capacity constraint.",
      "industries.uc5.body": "A public infrastructure agency has more tender packages to review than internal engineering capacity allows. Builtly produces the structured tender-review documentation per submission, runs the consistency checks across packages, and surfaces deviations for human judgment. The partner consultancy handles attestation.",
      "industries.uc5.outcome": "Engineering bottleneck inside the agency is unlocked. Procurement cadence accelerates without compromising review quality.",
      "industries.uc5.delivery.v": "Reviewed",
      "lbl.delivery": "Delivery",
      "industries.r1.name": "Platform licence",
      "industries.r1.desc": "For consultancies",
      "industries.r1.body1": "The primary engagement model. A consultancy licenses the full platform for use across its engineering teams. Implementation, jurisdictional configuration and team onboarding included.",
      "industries.r1.body2": "Suitable for consultancies with regular deliverable volume across multiple disciplines. The most economic route at scale.",
      "industries.r1.onboarding.k": "Onboarding",
      "industries.r1.onboarding.v": "Same week",
      "industries.r2.name": "Direct purchase",
      "industries.r2.desc": "For end buyers",
      "industries.r2.body1": "Direct purchase from the portal, one deliverable at a time. The buyer uploads project inputs, selects the module and delivery tier, and receives the output in their preferred format. No licence, no implementation overhead.",
      "industries.r2.body2": "Suitable for developers, lenders and asset managers buying automated-tier deliverables on demand. Engineer-reviewed and attested tiers also available where required.",
      "industries.r2.onboarding.v": "Same day",
      "industries.r3.name": "Partner integration",
      "industries.r3.body2": "Suitable for high-volume integrations and where the platform's outputs are inputs to a broader workflow.",
      "industries.r3.onboarding.v": "6–12 weeks",
      "industries.insight.accent": "The same engineering rigour, regardless of who is buying.",
      "industries.insight.lead": "One platform, three commercial routes.",
      "industries.insight.attr": "— The commercial principle",
      "industries.cta.btn.open_portal": "Open the portal",
      "industries.cta.row.licence.k": "Platform licence",
      "industries.cta.row.direct.k": "Direct purchase",
      "industries.cta.row.partner.k": "Partner integration",
      "industries.cta.row.response.k": "Response",
      "industries.cta.row.response.v": "Within 2 days",
      "trust.title": "Trust · Builtly Engineering",
      "trust.desc": "Trust at Builtly Engineering — security architecture, data handling, audit and regulatory compliance for engineering deliverables.",
      "trust.btn.all_routes": "All contact routes",
