      "industries.uc1.h4": "Site acquisition under timeline pressure.",
      "industries.uc1.buyer": "Real-estate developer",
      "industries.uc1.body": "A developer is bidding on a site with a one-week exclusivity window. The traditional path requires a two-week consultancy feasibility study. Builtly returns the indicative volume, regulatory envelope and climate-risk overlay the same day, with engineer-reviewed depth available within 48 hours if the deal advances.",
