      "industries.uc2.buyer": "Bank / construction lender",
      "industries.uc2.body": "A lender originates hundreds of construction loans per year. Manual technical review per loan is prohibitive, but skipping it surfaces problems too late. Builtly produces the technical-credit basis and ongoing-monitoring framework automatically per loan, with engineer escalation flagged where complexity warrants.",
      "industries.uc2.outcome": "Volume that was uneconomic to review manually becomes routine. Risk surfaces earlier in the lending cycle.",
