      "industries.uc3.buyer": "Asset manager / institutional investor",
      "industries.uc3.body": "A real-estate fund manager is required to disclose climate-risk exposure across portfolio assets under financial-sector climate-disclosure rules. Builtly produces structured per-asset climate-risk outputs for the entire portfolio, with audit trail and methodology suitable for regulatory submission.",
