      "platform.hero.eyebrow": "The Builtly platform",
      "platform.hero.h1": "The platform<br/>in detail.",
      "platform.insight.quote": "“The platform is one system, fifteen modules deep. <span class=\"accent\">New disciplines plug into the same architecture.</span>”",
      "platform.hero.lede": "Proprietary discipline engines from feasibility study to detailed design: geotechnics, structural, fire, acoustics and traffic, with supporting modules. Fifteen engineering modules across three delivery tiers, all running on the same architecture. Every module accepts open-format inputs, applies discipline-specific computation under regulatory constraint, and produces deliverables in the formats engineering consultancies actually use. <span class=\"serif\">One platform. Every discipline.</span>",
