      "index.bim.h2": "The platform reads<br/>BIM as design input.",
      "index.bim.lede": "Builtly reads an actual BIM model and turns it into structured engineering input. The platform classifies the elements, proposes the load-bearing system and works out the building's structural principles — from basement to roof. <span class=\"serif\">What was once a model now becomes a basis for decisions.</span>",
