      "about.glance.lede": "Builtly Engineering is an engineering automation platform built for the Nordic and German markets. Below: the operational facts as of public launch — scope, scale, and architecture.",
      "about.glance.c1.k": "Founded",
      "about.glance.c1.d": "Norway-based, structured for Nordic + DACH deployment.",
      "about.glance.c2.k": "Markets",
