      "about.glance.c3.k": "Disciplines",
      "about.glance.c3.suffix": "engineering",
      "about.glance.c3.d": "Structural, geotechnical, fire, acoustics, architectural, building physics.",
      "about.glance.c4.k": "Modules",
      "about.glance.c4.d": "Operational across the platform — analysis, compliance, reporting, BIM.",
      "about.glance.c5.k": "Architecture",
      "about.glance.c6.k": "Integrations",
      "about.glance.c6.d": "Authority registries, BIM tools, project-management and document systems.",
