      "index.demo.algo": "Gaussian quadrature",
      "index.tier.fn.h": "Functional modules in daily engineering delivery",
      "index.tier.cm.h": "Complementary deliverables for the full project lifecycle",
      "index.h4.computation": "Computation",
      "index.p.computation": "Spatial computation, numerical methods, mathematical optimization, constraint propagation. These are deterministic engines that produce verifiable answers. The platform delivers exact geometry and physics — not approximations described in prose.",
      "index.p.voronoiExplain": "Each cell is the region of floor space closest to one column — the area whose self-weight and live load that column carries. The result is the tributary load on every column, computed exactly from the floor plate geometry alone.",
      "index.p.thesis": "Consulting engineering is built on professional accountability, regulation and quality assurance — all correct. Beneath that lies repetitive cognitive work that consumes senior capacity. Builtly automates this layer; the engineer retains the signature.",
      "index.p.hero1": "Proprietary discipline engines from feasibility study to detailed design: geotechnics, structural, fire, acoustics and traffic, with supporting modules. Builtly Engineering is a client portal where geometry, physics, mathematics and AI converge on the complete engineering deliverable — under regulatory authority, with full audit trail. Operating in seven jurisdictions.",
      "index.p.hero2": "One platform for drawing, calculation and analysis. No switching between four tools to ship one report. AI handles the routine production work; the engineer reviews and signs. The portal is live and modules are operational today across structural, geotechnical, fire, acoustic and environmental disciplines.",
      "index.p.pipeline": "A processing pipeline where each stage is built to do one thing properly. Geometry and physics are deterministic. AI operates under regulatory constraint expressed as machine-readable rule sets. Engineers attest under regulatory authority. Every decision is traceable from source data to signed deliverable.",
      "index.p.tier": "The platform is delivered modularly. All modules are operational today — core disciplines are commercially prioritised, while supplementary modules run alongside in active development and customer pilot deployments.",
      "index.p.delivery": "From fully automated production to attested delivery.",
      "index.p.tierAuto": "The platform produces the deliverable end-to-end by combining data flow, computation logic, geometry, physics, mathematics and regulation. Used where the market accepts fully automated output as decision basis — such as climate risk, screening and tender checklists.",
      "index.p.tierReviewed": "The platform produces the draft and the documentation. A qualified engineer reviews, corrects and approves. Used where engineering judgment is required, but without formal attestation or legal signature.",
      "index.p.tierAttested": "The platform produces the foundation. A qualified professional with the right expertise and regulatory authority quality-controls and signs. Used for deliverables that carry legal liability and require professional indemnity coverage.",
      "index.p.scaling": "Builtly does not scale by building new platforms per country. It scales by plugging new regulation packs into the same core infrastructure. New jurisdictions onboard in weeks rather than years.",
      "index.p.cta": "Upload an IFC, DWG or floor plan. Run a rationality analysis, a climate risk report or a feasibility study. Get the result back in minutes — engineer-reviewed where it matters, attested where regulation requires it.",
      "index.k.totalArea": "Total area",
      "index.k.largestCell": "Largest cell",
      "index.k.complexity": "Complexity",
      "index.k.humanInput": "Human input",
      "index.k.scalability": "Scalability",
      "index.k.turnaround": "Turnaround",
      "index.k.access": "Access",
