      "about.bim_meta": "BIM · 102×60×20m · 6 floors · live",
      "industries.thesis_full": "The proposition is straightforward. <strong>Engineers spend the majority of their time on documentation and report production — work that consumes senior capacity without using the professional judgment it actually requires.</strong> Builtly is the tool for firms that want to redirect senior capacity to the work that requires it. AI handles the routine layer; the engineer's time goes where it matters.",
