      "sk.title": "Builtly Salgskonsoll · Salg og marked for boligprosjekter på ett sted",
      "sk.x_cta": "Se Prosjekthotellet",
      "sk.x_h": "Dokumenter, BIM og byggeplassen?",
      "sk.x_p": "Prosjekthotellet er prosjektets samhandlingsrom: dokumenter med revisjonskontroll, BIM i nettleseren, anbudsrom og byggeplass-innsjekk — samme prosjekt, oppstrøms.",
      "sw.prod.h2": "Produktene.",
      "sw.prod.maps.d": "Kart- og informasjonsportalen for eiendom: matrikkel, eierstruktur, regulering, risiko og verdiestimat for enhver adresse — med leietaker- og tomteradar. Norge og Sverige.",
      "sw.prod.maps.h": "Eiendomskart — Builtly Maps",
      "sw.prod.maps.l": "Se Builtly Maps",
      "sw.prod.ms.d": "Fra eiendom til beslutningsgrunnlag: tomta fra matrikkelen, reguleringen lest, komplette utbyggingsalternativer med arealer, sol/skygge og prosjektøkonomi — rapport til styret og banken.",
      "sw.prod.ms.h": "Mulighetsstudie",
      "sw.prod.ms.l": "Se Mulighetsstudien",
      "sw.prod.ph.d": "Det intelligente samhandlingsrommet: dokumenter med revisjonskontroll, BIM rett i nettleseren, komplett anbudsrom, byggeplass-innsjekk etter § 15, FDV-registeret som tar bygget inn i drift — og Builtly Control for produktdokumentasjon og etterlevelse på samme prosjekt.",
      "sw.prod.ph.h": "Prosjekthotell",
      "sw.prod.ph.l": "Se Prosjekthotellet",
      "sw.prod.s": "Produkter",
      "sw.ctl.badge": "Nytt · tidlig tilgang",
      "sw.ctl.cta": "Logg inn i Control",
      "sw.ctl.h": "Builtly Control — produktdokumentasjon og etterlevelse",
      "sw.ctl.mer": "Les mer om Builtly Control",
      "sw.ctl.p": "Byggevarene i prosjektet, dokumentasjonen bak dem og kravene de skal oppfylle — DoP, SDS, EPD og FDV — i én arbeidsflate. Hva som mangler måles av dokumentene ved lesing, aldri av et flagg; mangler får ansvarlig og frist. Som eget produkt, eller aktivert på et prosjekt i Prosjekthotellet.",
      "sw.ctl.s1": "Produktregister",
      "sw.ctl.s2": "Krav og avvik",
      "sw.ctl.s3": "Revisjonsspor",
      "sw.prod.render.d": "Fra arkitektmodell til fotorealistiske bilder — modelltro fra IFC-en, eller fra et bilde du alt har.",
      "sw.prod.render.h": "Builtly Render",
      "sw.prod.render.l": "Utforsk Builtly Render",
