      "nav.industries":          "Bransjer",
      "nav.maps": "Kart",
      "nav.bimViewer": "BIM",
      "nav.bimViewerFull": "BIM Viewer",
      "bimv.title": "Builtly BIM Viewer · Gratis IFC-viser i nettleseren",
      "bimv.meta": "Builtly BIM Viewer — åpne IFC-modeller rett i nettleseren, gratis. Mål lengder og arealer, les arealer og boenheter ut av modellen. Filen forlater aldri maskinen din. Gratis for bedrifter og privatpersoner.",
      "bimv.smark.label": "Builtly BIM Viewer",
      "bimv.smark.tag": "Gratis IFC-viser",
      "bimv.h1": "Åpne BIM-modeller<br/>rett i nettleseren.",
      "bimv.lede": "Dra en IFC-fil inn i nettleseren, så åpner den seg — ingen installasjon, ingen lisens, ingen selskapsregistrering. Mål lengder og arealer, snitt modellen, og les arealer og boenheter rett ut av den. Filen leses lokalt på din maskin og lastes aldri opp. Gratis for bedrifter og privatpersoner.",
      "bimv.cta.open": "Åpne BIM Viewer — gratis",
      "bimv.cta.plans": "Se hva som er med",
      "bimv.cta.short": "Åpne BIM Viewer",
      "bimv.stage.live": "Live",
      "bimv.stage.local": "✓ Lest lokalt — aldri lastet opp",
      "bimv.stage.free": "Gratis i nettleseren",
      "bimv.chip.elements": "Elementer",
      "bimv.chip.floors": "Etasjer",
      "bimv.chip.bra": "Areal",
      "bimv.chip.units": "Boenheter",
      "bimv.chip.measure": "Måling",
      "bimv.chip.schema": "Format",
      "bimv.tool.measure": "Måling",
      "bimv.tool.area": "Arealanalyse",
      "bimv.tool.units": "Boenheter",
      "bimv.tool.section": "Snitt",
      "bimv.feat.browser.label": "IFC i nettleseren",
      "bimv.feat.browser.h": "Ingen installasjon. Ingen lisens.",
      "bimv.feat.browser.p": "Dra inn en IFC-fil, så åpner den seg — IFC 2x3 og IFC 4, fra Revit, ArchiCAD og resten. Ekte prosjektmodeller på hundre megabyte og mer, lest med en strømmende leser bygget for byggeplass-PC-er og nettbrett.",
      "bimv.feat.privacy.label": "Personvern i bunn",
      "bimv.feat.privacy.h": "Filen forlater aldri maskinen din.",
      "bimv.feat.privacy.p": "Gratis-viseren leser modellen lokalt i nettleseren — ingenting lastes opp, lagres eller logges. Åpne en konfidensiell anbudsmodell uten å sende den noe sted. Det er ikke et løfte i en policy; det er slik viseren er bygget.",
      "bimv.feat.measure.label": "Måleverktøy",
      "bimv.feat.measure.h": "Mål lengder og arealer.",
      "bimv.feat.measure.p": "Dobbeltklikk to punkter for en lengde, hjørne for hjørne for et areal. Snitt modellen, isolér bærende konstruksjon, og klikk et element for egenskapene.",
      "bimv.feat.area.label": "Arealanalyse",
      "bimv.feat.area.h": "Arealer rett ut av modellen.",
      "bimv.feat.area.p": "Brutto- og nettoarealer, salgbart areal og etasjevis fordeling — lest av modellens egne flater og dekker, med en ærlig rimelighetskontroll som flagger skalafeil og blandede lag i stedet for å gjette.",
      "bimv.feat.units.label": "Boenheter",
      "bimv.feat.units.h": "Teller enheter — også uten rom.",
      "bimv.feat.units.p": "Mange ARK-eksporter har ingen romobjekter i det hele tatt. Viseren måler enhetssignaler — inngangsdører i leilighetsskillevegger, bekreftet av kjøkken og møbler — og viser alle konkurrerende signaler, så en feil tolkning er synlig og aldri skjult.",
      "bimv.feat.save.label": "Modellbibliotek",
      "bimv.feat.save.h": "Lagre modeller når du trenger det.",
      "bimv.feat.save.p": "Å se er gratis, alltid. Vil du beholde modeller i et bibliotek og åpne dem fra hvilken som helst maskin, koster lagring 199 kr per måned — aktiveres i viseren, faktureres på e-post, avsluttes når du vil.",
      "bimv.plan.free.name": "Gratis",
      "bimv.plan.free.f1": "Åpne IFC-modeller i nettleseren — ubegrenset",
      "bimv.plan.free.f2": "Måleverktøy, snitt, arealanalyse og boenhetstelling",
      "bimv.plan.free.f3": "Filene leses lokalt og lastes aldri opp",
      "bimv.plan.free.f4": "Registrer deg med e-post — ingen selskap kreves",
      "bimv.plan.pro.name": "Lagring",
      "bimv.plan.pro.per": "per måned",
      "bimv.plan.pro.f1": "Alt i Gratis",
      "bimv.plan.pro.f2": "Lagre modeller i ditt eget bibliotek",
      "bimv.plan.pro.f3": "Åpne modellene dine fra hvilken som helst maskin",
      "bimv.plan.pro.f4": "Faktureres på e-post — avslutt når du vil",
      "bimv.plan.pro.note": "Aktiveres i viseren når du først lagrer en modell — ingen kort, ingen bindingstid.",
      "bimv.diff.h": "En del av Builtly-plattformen.",
      "bimv.diff.c1": "Prosjekthotell / CDE",
      "bimv.diff.c2": "Samordningsmodell",
      "bimv.diff.c3": "Anbudsrom",
      "bimv.diff.c4": "Fagmoduler",
      "bimv.diff.p": "Viseren kjører på samme BIM-motor som Builtlys prosjekthotell — der fagmodellene federeres til én fellesmodell, anbudspakker sendes med kvittering, og konstruksjons-, brann-, akustikk- og geoteknikkleveranser produseres på plattformen. Trenger teamet mer enn visning, skriv til <a href=\"mailto:sales@builtly.ai\" style=\"color:#5EEAD4\">sales@builtly.ai</a> eller <a href=\"/bli-kunde.html\" style=\"color:#5EEAD4\">bli kunde</a>.",
      "maps.smark.label": "Builtly Maps",
      "maps.smark.tag": "Eiendomsintelligens",
      "maps.h2": "Hver eiendom —<br/>fra kart til ingeniørleveranse.",
      "maps.lede": "Builtly Maps samler levende eiendomsdata — matrikkel, eierskap, regulering, risiko og areal — for enhver adresse, eier eller selskap. Bygget for arkitekter, utbyggere og eiendomsaktører. Og fordi det kjører på Builtly-plattformen, kan du koble på ingeniørmodulene og ta en eiendom rett fra et kartoppslag til en kvalitetssikret leveranse.",
      "maps.f1.label": "Datalaget",
      "maps.f1.h": "Hver eiendom, live.",
      "maps.f1.p": "Søk på adresse, eiendom, eier eller selskap. Matrikkel, areal, BYA/BRA, hjemmelshavere og eierstruktur — hentet live fra Kartverket og Brønnøysund. Risikolag for flom, kvikkleire, stormflo og grunnforhold, med regulering, kartlag, områdeanalyse og saksinnsyn.",
      "maps.f2.label": "Forskjellen",
      "maps.f2.h": "Ikke bare data — ingeniørarbeid.",
      "maps.f2.p": "Der andre verktøy stopper ved dataene, kobler Builtly Maps på ingeniørmodulene — konstruksjon, geoteknikk, brann, akustikk, klimarisiko og verdivurdering. Gå fra en eiendom på kartet helt til beregninger, dokumentasjon og en signert leveranse, på én plattform.",
      "maps.cta.open": "Åpne Builtly Maps",
