      "maps.country.uk": "Storbritannia",
      "maps.cta.demo": "Book en demo",
      "maps.diff.h": "Ikke bare dataene — ingeniørarbeidet.",
      "maps.diff.p": "Andre plattformer stopper ved dataene. Fordi Builtly Maps kjører på Builtly ingeniørplattform, kan du ta en eiendom rett fra et kartoppslag til leveranser innen konstruksjon, geoteknikk, brann, akustikk, klimarisiko og verdivurdering — beregnet, dokumentert og signert. I tillegg får du porteføljeoversikt, prosjektpipeline, forklarbare leads og ditt eget datarom.",
      "maps.feat.search.label": "Søk & eierskap",
      "maps.feat.search.h": "Enhver eiendom, enhver eier.",
      "maps.feat.search.p": "Søk på adresse, eiendom, eier eller selskap. Live matrikkel, areal, BYA/BRA, hjemmelshavere og fullstendige eierstrukturer fra Kartverket og Brønnøysund — med en åpen-data eierrisiko-indikator.",
      "maps.feat.deepdive.label": "Eiendomsdypdykk",
      "maps.feat.deepdive.h": "Alt om én eiendom.",
      "maps.feat.deepdive.p": "Åpne enhver eiendom til tomt, verdiestimat fra sammenlignbare salg i nabolaget, transaksjonshistorikk, eiere, leietakere, omkringliggende område og registrerte byggesaker.",
      "maps.feat.mapanalysis.label": "Kartanalyse",
      "maps.feat.mapanalysis.h": "Tegn, mål, analyser.",
      "maps.feat.mapanalysis.p": "Slå på kartlag, tegn og analyser et hvilket som helst område, og mål avstander. Risikolag for flom, kvikkleire, stormflo og grunnforhold, pluss regulering — i 2D, 3D, kart eller flyfoto.",
      "maps.feat.area.label": "Områderapporter",
      "maps.feat.area.h": "Kjenn markedet.",
      "maps.feat.area.p": "Umiddelbare områdeprofiler — befolkning, demografi, boligpriser mot byggekostnad, og nybyggtilbud med median kr/m², enheter og romfordeling. Eksporterbart til PDF.",
      "maps.feat.tenant.label": "Leietaker-radar",
      "maps.feat.tenant.h": "Finn leietakere først.",
      "maps.feat.tenant.p": "Finn selskaper som snart trenger nye lokaler — før konkurrentene. Rangert på vekst, bransje og fase, med begrunnelsen bak hvert signal og en vei til kontakt.",
      "maps.feat.plot.label": "Tomte-radar",
      "maps.feat.plot.h": "Finn byggbar tomt.",
      "maps.feat.plot.p": "Finn ubebygde, byggbare tomter i en hvilken som helst kommune etter areal, med beregnet utbyggingspotensial (BYA) og regulering — samlet på kartet og i en eksporterbar tabell.",
      "nav.howItWorks":          "Slik fungerer det",
