      "hero.eyebrow":            "Fremtidens ingeniørselskap. Allerede her.",
      "hero.h1":                 "Banebrytende i hvert fag. Samlet om ett prosjekt.",
      "hero.lede.body": "Builtly er ikke én app som gjør litt av alt. Det er dype fagsystemer — areal og avkastning, brann, konstruksjon, salg, dokumentasjon — bygget sammen med ledende fagingeniører, på én modell av prosjektet fra tomt til drift.",
      "hero.lede.tagline": "Ledende fagspesialister. Banebrytende teknologi. Skalerbare ingeniørleveranser.",
