      "platform.hero.eyebrow": "Builtly-plattformen",
      "platform.hero.h1": "Plattformen<br/>i detalj.",
      "platform.insight.quote": "«Plattformen er ett system, femten moduler dypt. <span class=\"accent\">Nye disipliner kobler seg på samme arkitektur.</span>»",
      "platform.hero.lede": "Egne fagmotorer fra mulighetsstudie til ferdig prosjektering: geoteknikk, konstruksjon, brann, akustikk og trafikk, med tilhørende støttemoduler. Femten ingeniørmoduler på tvers av tre leveransenivåer, alle på samme arkitektur. Hver modul aksepterer åpne formater, kjører disiplinspesifikk beregning under regulatoriske rammer, og produserer leveranser i formatene ingeniørkonsulenter faktisk bruker. <span class=\"serif\">Én plattform. Hver disiplin.</span>",
