      "about.hero.eyebrow": "Om Builtly Engineering",
      "about.hero.h1": "Skapt av gründere.<br/>Bygget av ingeniører.<br/>For ingeniører.",
      "about.insight.quote": "«Builtly leverer startpunktet. <span class=\"accent\">Ingeniøren leverer ingeniørfaget.</span>»",
      "about.hero.lede": "Builtly Engineering er konvergensen av tre sjeldne disipliner under ett tak: profesjonelt ingeniøransvar, kapitalmarkedserfaring fra eiendom, og moderne programvareutvikling. <span class=\"serif\">Det er ikke tilfeldig. Det er forutsetningen.</span>",
