      "careers.hero.lede": "Builtly er et lite, bevisst team som bygger om produksjonslaget i ingeniørkonsulent­bransjen. Arbeidet er teknisk krevende, profesjonelt ansvarlig og uvanlig konsekvensrikt. <span class=\"serif\">Vi ansetter for vurderingsevne, dybde og langt perspektiv.</span>",
