      "contact.hero.eyebrow": "Kontakt Builtly Engineering",
      "contact.hero.h1": "Ta kontakt.",
      "contact.hero.lede": "Fire ruter, fire innbokser, fire responstider — valgt for å få henvendelser til riktig person raskt. Velg ruten som passer det du trenger, og skriv til adressen under. <span class=\"serif\">Ingen skjemaer å fylle ut. Ekte mennesker i andre enden.</span>",
