      "trust.hero.eyebrow": "Tillit hos Builtly Engineering",
      "trust.hero.h1": "Bygget for regulert arbeid.",
      "trust.insight.quote": "«Etterlevelse er ikke en funksjon. <span class=\"accent\">Det er en egenskap ved hvordan plattformen er bygd.</span>»",
      "trust.hero.lede": "Builtly produserer leveranser som en ingeniør signerer under profesjonelt ansvar, og som kunden bruker i rettslig holdbare regulatoriske innleveringer. <span class=\"serif\">Plattformen er bygget etter den standarden fra grunnen av — ikke som en funksjon påklistret for innkjøp.</span>",
