      "flow.lede": "I et tradisjonelt prosjekt utveksler fire kontorer 47 dokumenter over seks uker før noen signerer noe. Builtly tar imot de samme fire input-strømmene, prosesserer dem i én kjerne, og leverer fire signerte output-strømmer på timer. Under: strømmen er live.",
