      "sec.steinan.lede": "En 9-etasjes boligblokk. <b>1 070 vegger, 566 dører, 263 vinduer</b> fordelt over PLAN 00 til PLAN 06, pluss en halv-mesanin på PLAN 05-A. Plattformen leser hver etasje på millisekunder — separerer nivåer, mapper høyder, klassifiserer elementer. Under: kompleksiteten i hver etasje, avdekket nivå for nivå.",
