      "index.pipe.s2.l1": "Hybrid AI",
      "about.glance.c5.d": "Multi-motor, deterministisk beregning. Egne modeller kombinert med Anthropic-kapasiteter (Claude) under regulatoriske rammer.",
      "platform.f.ai": "Hybrid AI-arkitektur.",
      "plt.found.ai.p": "Hybrid multi-motor arkitektur som kombinerer egne ingeniør­modeller med selektivt påkalte Anthropic-kapasiteter (Claude). Hver forespørsel rutes til motoren som er best egnet for oppgaven — egne modeller for ingeniør­spesifikk resonnering, tredjeparts­modeller for generelt språk og strukturert ekstraksjon. Alle motorer opererer under regulatoriske rammer; utdata styres av regelpakken, ikke av AI-ens selvtillit.",
      "platform.s01.lede": "Plattformen er ett system med ett sett fundamenter — hybrid AI som orkestrerer egne og Anthropic-modeller (Claude), deterministisk beregning, reguleringsmotor, revisjonsspor. Moduler er innpakninger rundt de samme fundamentene.",
      "trust.c5.body": "Builtly opererer en hybrid AI-arkitektur. Egne ingeniør­modeller trenes på ingeniør­litteratur, offentlig regulatorisk tekst og syntetiske ingeniør­datasett — aldri på kundens prosjekt­data. Tredjeparts­modeller fra Anthropic (Claude) påkalles gjennom deres standard-API-er under databeskyttelses­vilkår som forbyr trening på kunde­input. Kunder som ønsker at deres anonymiserte data skal bidra til modellforbedring kan velge inn under et separat tillegg, men standarden er ingen trening, uten unntak, på tvers av hver modell i stakken. I mulighetsstudie-modulen brukes i tillegg Google Gemini til bildegenerering under samme vilkår. OpenAI brukes ikke noe sted på plattformen.",
      "careers.r1.r2.desc": "Bygg og finstill hybrid AI-arkitekturen bak Builtly. Multi-motor orkestrering av egne og Anthropic-modeller (Claude), regulerings­begrenset inferens, og regelpakke-gatene som styrer utdata.",
      "careers.pos.1.name": "Senior plattform-ingeniør",
      "careers.pos.1.desc": "Bygg den underliggende plattformen som ingeniør­modulene kjører på. Backend-arkitektur, distribuerte systemer, data-pipelines og integrasjon med regulatoriske data­kilder. Sterk system­ingeniør­bakgrunn.",
      "careers.pos.1.meta": "Ingeniørarbeid",
      "careers.pos.1.type": "Heltid · Fjernarbeid",
      "careers.pos.2.name": "AI-ingeniør · Hybrid arkitektur",
      "careers.pos.2.desc": "Bygg og finstill hybrid AI-arkitekturen bak Builtly. Multi-motor orkestrering av egne og Anthropic-modeller (Claude), regulerings­begrenset inferens, vision-basert parsing av ingeniør­dokumenter. Senior ML- eller forsknings­ingeniør-bakgrunn.",
      "careers.pos.2.meta": "AI / ML",
      "careers.pos.2.type": "Heltid · Fjernarbeid",
      "careers.pos.3.name": "Algoritme­ingeniør · Matematikk",
      "careers.pos.3.desc": "Implementer de deterministiske numeriske algoritmene bak strukturelle, geotekniske og akustiske beregninger. Element­metoder, beregnings­geometri, numerisk optimering. Sterk matematikk- og ingeniør­beregnings­bakgrunn.",
      "careers.pos.3.meta": "Ingeniørarbeid",
      "careers.pos.3.type": "Heltid · Fjernarbeid",
      "careers.pos.4.name": "Seniorrådgiver · Geoteknikk",
      "careers.pos.4.desc": "Senior geoteknisk ingeniør med regulatorisk myndighet til å attestere leveranser. Arbeid på plattformens geotekniske modul, bidra til regelpakke-utvikling, og signere Eurokode-7-leveranser. Dyp praktisk erfaring kreves.",
      "careers.pos.4.meta": "Disiplin · Geoteknikk",
      "careers.pos.4.type": "Senior · Hybrid",
      "careers.pos.5.name": "Seniorrådgiver · Konstruksjon",
      "careers.pos.5.desc": "Senior konstruksjons­ingeniør med regulatorisk myndighet til å attestere leveranser. Led utviklingen av konstruksjons­modulen — Eurokode-1 til Eurokode-9, BIM-integrasjon, IFC4-modell­håndtering. Dyp BIM-nativ praktisk erfaring kreves.",
      "careers.pos.5.meta": "Disiplin · Konstruksjon",
      "careers.pos.5.type": "Senior · Hybrid",
      "careers.pos.6.name": "Seniorrådgiver · Brannsikkerhet",
      "careers.pos.6.desc": "Senior brann­ingeniør med regulatorisk myndighet til å attestere leveranser. Led brann­sikkerhets­modulens regulerings­motor, brann­avdelinger og rømnings­beregninger, jurisdiksjons­spesifikk regelutrykk. Praktiserende brann­ingeniør med bred case-erfaring.",
      "careers.pos.6.meta": "Disiplin · Brann",
      "careers.pos.6.type": "Senior · Hybrid",
      "careers.pos.7.name": "Seniorrådgiver · Akustikk",
      "careers.pos.7.desc": "Senior akustikk-konsulent med regulatorisk myndighet til å attestere leveranser. Utvikle akustikk-modulens beregnings­motor, romakustikk og lyd­klasse-verifisering. Sterk portefølje av regulatoriske akustikk-leveranser kreves.",
      "careers.pos.7.meta": "Disiplin · Akustikk",
      "careers.pos.7.type": "Senior · Hybrid",
      "careers.pos.8.name": "Driftsdirektør",
      "careers.pos.8.desc": "Drift kommersiell virksomhet på tvers av kunde­relasjoner, partner­integrasjoner og onboarding. Bygg den operative rytmen som lar ingeniører fokusere på ingeniør­arbeid. Senior forretnings­drifts­bakgrunn med plattform-erfaring.",
      "careers.pos.8.meta": "Drift",
      "careers.pos.8.type": "Senior · Hybrid"
