        "industries.uc1.buyer": "Real-estate developer",
        "industries.uc1.body": "A developer has a short exclusivity window and needs a defensible first view of what the site can carry. Builtly turns available site data, planning constraints and climate-risk signals into a structured screening package, with reviewed depth available if the deal advances.",
        "industries.uc1.outcome": "The go/no-go decision is grounded in evidence before exclusivity expires, and the next engineering engagement starts with a clearer brief.",
        "industries.uc1.delivery.v": "Automated · Review-ready",
        "industries.uc2.h4": "Construction-loan review across many projects.",
        "industries.uc2.buyer": "Bank / construction lender",
        "industries.uc2.body": "A lender originates many construction loans and needs a consistent technical view across projects. Builtly structures the technical-credit basis, monitoring inputs and exception flags so human review can focus on the projects that need it most.",
        "industries.uc2.outcome": "Technical risk is surfaced earlier and compared more consistently across the lending cycle.",
        "industries.uc2.delivery.v": "Automated · API",
        "industries.uc3.h4": "Portfolio climate-risk disclosure.",
        "industries.uc3.buyer": "Asset manager / institutional investor",
        "industries.uc3.body": "A real-estate fund manager needs climate-risk and technical screening across a portfolio. Builtly produces structured per-asset outputs with methodology, source references and audit trail suitable for downstream reporting.",
        "industries.uc3.outcome": "The team gets a portfolio-wide first pass without commissioning every asset individually, while still knowing where expert review is required.",
        "industries.uc4.h4": "Consultancy delivery velocity.",
        "industries.uc4.buyer": "Engineering consultancy",
        "industries.uc4.body": "A consultancy has a queue of similar projects that all require a baseline assessment plus project-specific judgment. Builtly produces the structured baseline and supporting documentation; the engineer reviews, adjusts and attests the final output where required.",
        "industries.uc4.outcome": "Turnaround improves, review quality becomes more consistent and senior attention moves from formatting to engineering judgment.",
        "industries.uc4.delivery.v": "Attested",
        "industries.uc5.h4": "Public tender preparation under capacity constraint.",
        "industries.uc5.buyer": "Public agency · consultancy partner",
        "industries.uc5.body": "A public infrastructure agency has more tender packages to review than internal capacity allows. Builtly prepares structured review documentation, checks consistency across packages and surfaces deviations for the responsible team and consultancy partner.",
        "industries.uc5.outcome": "Procurement teams get a clearer review basis; consultants focus on deviations, judgment and attestation.",
        "industries.uc5.delivery.v": "Reviewed",
        "industries.s04.label": "Access routes",
        "industries.s04.tag": "How to engage",
        "industries.s04.h2": "Three access routes.",
        "industries.s04.lede": "The commercial route depends on who owns the workflow and whether outputs are used internally, reviewed by an engineer or formally signed. The platform is the same; the access model changes.",
        "industries.route.01": "§ Route 01",
        "industries.route.02": "§ Route 02",
        "industries.route.03": "§ Route 03",
        "industries.r1.name": "Platform licence",
        "industries.r1.desc": "For consultancies",
        "industries.r1.body1": "Best for engineering consultancies that want Builtly inside their production process. Access for technical teams and configuration for local rules and templates are included.",
        "industries.r1.body2": "Use this when the firm wants repeatable volume across disciplines while keeping the client relationship, review process and sign-off under its own control.",
        "industries.r1.onboarding.k": "Onboarding",
        "industries.r1.onboarding.v": "Same week",
        "industries.r2.name": "Direct purchase",
        "industries.r2.desc": "For project owners and buyers",
        "industries.r2.body1": "For individual projects and early technical decisions. The buyer uploads inputs, chooses a module and delivery level, and receives a structured output in the selected format.",
        "industries.r2.body2": "Best for developers, lenders and asset managers who need first-pass evidence quickly. Reviewed and attested routes are available when the use case requires it.",
        "industries.r2.onboarding.v": "Same day",
        "industries.r3.name": "Partner integration",
        "industries.r3.desc": "For platforms & consortia",
        "industries.r3.body1": "API integration or white-label arrangement for partners that embed Builtly capabilities in their own workflow — lender portals, proptech platforms, consultancy networks or public-sector consortia.",
        "industries.r3.body2": "Best for high-volume integrations where Builtly outputs become part of a broader customer or decision workflow.",
        "industries.r3.onboarding.v": "6–12 weeks",
        "industries.insight.lead": "One production layer. Three access routes.",
        "industries.insight.accent": "Professional accountability stays intact.",
        "industries.insight.attr": "— The commercial principle",
        "industries.s05.label": "Engage",
        "industries.s05.tag": "Choose the right route",
        "industries.s05.h2": "Find the right route.",
        "industries.cta.lede": "Tell us which route fits your workflow. Consultancies usually start with a platform-licence conversation. Developers, lenders and asset managers can test selected modules directly. Partners and integrators should contact us with the workflow they want to embed.",
        "industries.cta.btn.open_portal": "Open the portal",
