        "cookie.accept": "Greit",
        "cookie.privacyLink": "Personvern",
        "industries.title": "Bransjer · Builtly Engineering",
        "industries.desc": "Builtly er produksjonslaget for regulerte ingeniørleveranser — bygget for rådgivende ingeniørfirmaer og tilgjengelig for utviklere, långivere, forvaltere og offentlig sektor gjennom kontrollerte tilgangsmodeller.",
        "industries.hero.eyebrow": "Bransjer og brukere",
        "industries.hero.h1": "Bygget for rådgivende ingeniører.<br/>Nyttig for aktørene rundt dem.",
        "industries.hero.lede": "Builtly er produksjonslaget for regulerte ingeniørleveranser. Rådgivende ingeniørfirmaer bruker plattformen til å standardisere, akselerere og kvalitetssikre rapportproduksjon; utviklere, långivere, forvaltere og offentlige miljøer bruker utvalgte moduler når de trenger et strukturert teknisk grunnlag tidligere i beslutningsprosessen. <span class=\"serif\">Én plattform. Fagansvaret beholdes.</span>",
