        "industries.s01.pm.h4": "Moduler tilgængelige for rådgivere",
        "industries.s01.pm.desc": "Femten moduler på tværs af tre leveranceniveauer",
        "industries.mod.geo": "Geoteknik",
        "industries.mod.str": "Konstruktion",
