        "industries.mod.ark": "Mulighedsstudie",
        "industries.mod.tdd": "Teknisk DD",
        "industries.mod.bid": "Udbudsgennemgang",
        "industries.mod.qty": "Mængder",
        "industries.mod.hse": "Arbejdsmiljøplan",
        "industries.mod.cli": "Klimarisiko",
