        "industries.title": "Toimialat · Builtly Engineering",
        "industries.desc": "Builtly on tuotantokerros säännellyille insinööritoimituksille — rakennettu insinööritoimistoille ja saatavilla kehittäjille, rahoittajille, varainhoitajille ja julkiselle sektorille hallittujen käyttömallien kautta.",
        "industries.hero.eyebrow": "Toimialat ja käyttäjät",
        "industries.hero.h1": "Rakennettu insinööritoimistoille.<br/>Hyödyllinen myös niitä ympäröiville toimijoille.",
        "industries.hero.lede": "Builtly on tuotantokerros säännellyille insinööritoimituksille. Insinööritoimistot käyttävät alustaa raporttituotannon standardointiin, nopeuttamiseen ja laadunvarmistukseen; kehittäjät, rahoittajat, varainhoitajat ja julkiset toimijat käyttävät valittuja moduuleja, kun he tarvitsevat jäsennellyn teknisen perustan aiemmin päätöksenteossa. <span class=\"serif\">Yksi alusta. Ammatillinen vastuu säilyy.</span>",
        "industries.meta.r1.k": "Ensisijainen asiakas",
        "industries.meta.r1.v": "Insinööritoimistot",
        "industries.meta.r2.k": "Läheiset käyttäjät",
