        "industries.s01.h2": "The production layer for engineering consultancies.",
        "industries.s01.lede": "Builtly is designed around how engineering consultancies actually deliver: calculations, local rules, quality assurance, client revisions and signed documents. The platform does not replace professional responsibility; it removes the repetitive work around it.",
        "industries.s01.body1.intro": "The shift is practical.",
        "industries.s01.body1.bold": "Senior engineering capacity should be spent on judgment, exceptions and sign-off — not on rebuilding the same report structure from project to project.",
