        "industries.desc": "Builtly Engineering er først og fremst bygget for rådgivende ingeniører og brukes også av utbyggere, banker, eiere og offentlig sektor. Plattformen automatiserer standardiserte ingeniørleveranser med kvalitetssikring og signering der det kreves.",
