        "industries.hero.h1": "Bygget først for rådgivende ingeniører.<br/>Brukt på tvers av bransjen.",
        "industries.hero.lede": "Builtlys primærkunde er rådgivende ingeniører og konsulentselskaper som produserer signerte, regulerte leveranser. Den samme plattformen brukes også av utbyggere, banker, eiere og offentlig sektor gjennom direkte moduler, partnermodeller og leveranser med faglig kvalitetssikring.",
