      "ref.p2.d": "The model carried no room objects at all. Housing, commercial space and parking were separated and measured directly from the building elements, with every competing signal visible — a wrong reading must be discoverable, never hidden.",
      "ref.p2.f1k": "Project type",
      "ref.p2.f1v": "Housing, commercial and parking",
      "ref.p2.f2k": "Builtly's role",
      "ref.p2.f2v": "Technical analysis",
      "ref.p2.f3k": "Technology",
      "ref.p2.f3v": "BIM engine · area analysis",
      "ref.p2.h": "Mixed-use project — 63 homes",
      "ref.p2.r": "BIM analysis · area measurement · unit verification",
      "ref.p3.d": "Fire compartments, escape routes and door classes derived against the fire chapter of the building regulations and drawn as deliverable sheets with title blocks — controlled by a fire engineer before use.",
      "ref.p3.f1k": "Project type",
      "ref.p3.f1v": "Residential block, staged",
      "ref.p3.f2k": "Builtly's role",
      "ref.p3.f2v": "Fire-engineering production and control",
      "ref.p3.f3k": "Technology",
      "ref.p3.f3v": "Fire engine · TEK17 ch. 11",
      "ref.p3.h": "Fire concept, residential block — stage 2",
      "ref.p3.r": "Fire drawing production with professional control",
      "ref.p4.d": "Quality assurance of a 2.7-million-line ArchiCAD export without room objects: terrain separated from housing area, units measured from door signals in party walls, and the federated model served in the browser.",
      "ref.p4.f1k": "Project type",
      "ref.p4.f1v": "Apartment buildings, several stages",
      "ref.p4.f2k": "Builtly's role",
      "ref.p4.f2v": "Model QA and coordination",
      "ref.p4.f3k": "Technology",
      "ref.p4.f3v": "BIM engine · federated model",
      "ref.p4.h": "Coastal project — 153 apartments, federated model",
      "ref.p4.r": "Model control · coordination · unit counting",
      "ref.p5.d": "Landing page on the project's own domain, browsable prospectus, consent-based prospect registration, broker alerts and a Friday report to the developer — sales rate and pace measured continuously.",
      "ref.p5.f1k": "Project type",
      "ref.p5.f1v": "Row houses, apartments and detached homes",
      "ref.p5.f2k": "Builtly's role",
      "ref.p5.f2v": "Sales and marketing support",
