      "ref.p5.h": "Housing development — sales & marketing, 19 units",
      "ref.p5.r": "Sales console · project website · prospectus",
      "ref.p6.d": "Tender basis built from the project hotel's folders with frozen revisions, transmitted to each bidder with a personal link and receipt — and an anonymous Q&A round with answers published to all.",
      "ref.p6.f1k": "Project type",
      "ref.p6.f1v": "Design & build, residential",
