      "ref.side3v": "Consulting + software",
      "ref.title": "References · Builtly",
      "sjv.desc": "Builtly can do the job for you — or give you the technology to do it yourself. Three delivery models: consulting engagement, software, and combined delivery.",
      "sjv.eyebrow": "Builtly · How we work",
      "sjv.garanti_h": "When we both collaborate and compete",
      "sjv.garanti_p": "Builtly sells software to consultancies — and takes on consulting engagements of its own. That is why the separation is absolute: Builtly Engineering has no access to software customers' projects unless the customer explicitly invites Builtly in or orders a consulting service. Software customers' clients, project information and usage patterns are not used for sales or competing bids. The customer owns the data, and project data is never used to train models.",
      "sjv.h1": "Builtly can do the job for you — or give you the technology to do it yourself.",
      "sjv.lede": "One Builtly, two business areas — and a combination when the project requires it. These are the three ways the market uses us, and the principles that apply in every model.",
      "sjv.m1.cta": "See the consulting services",
      "sjv.m1.h": "01 · Builtly as your consultant",
      "sjv.m1.p": "You buy a normal consulting delivery. Builtly's engineers attend meetings, design, make professional judgements, coordinate, quality-assure, sign and follow up the project. You do not need to buy software or change how you work.",
      "sjv.m2.cta": "See the software area",
      "sjv.m2.h": "02 · You use the software yourself",
      "sjv.m2.p": "The customer or partner uses Builtly's modules in their own organisation and on their own projects — maps and analysis, engineering, economics, sales, collaboration and finance. Access and licensing are agreed per module.",
      "sjv.m3.cta": "Request a quote",
      "sjv.m3.h": "03 · Combined delivery",
      "sjv.m3.p": "You use the Builtly module yourself — and Builtly assists with professional assessment, controls or completes the deliverable, and takes responsibility and signs where agreed. The scope is agreed per deliverable, so you pay for exactly the professional assistance you need.",
      "sjv.modell_tag": "Delivery model",
      "sjv.p1.d": "Builtly's engineers hold the professional responsibility and deliver the engagement. Our groundbreaking software is used as a tool in the design work where it improves quality, traceability and workflow — the judgements, the coordination and the signature belong to the engineer.",
      "sjv.p1.t": "The engineer holds the professional responsibility",
      "sjv.p2.d": "The delivery is never just a report: updated IFC, discipline model, drawings as DWG/DXF, deviations as BCF and quantities to NS 3420 — formats you can keep working in.",
      "sjv.p2.t": "Editable discipline formats, always",
      "sjv.p3.d": "Measurements and assessments are documented with source and reservations. An honest “this needs clarification” is worth more than a pretty number no one can trust.",
      "sjv.p3.t": "Where the basis is ambiguous, we never guess",
      "sjv.p4.d": "Every delivery traces back to the input, the calculations and the person who controlled and signed — with revisions, receipts and a complete history.",
      "sjv.p4.t": "Traceability from input to delivery",
      "sjv.pr1.d": "Describe the project — we respond within one business day.",
      "sjv.pr1.n": "Inquiry",
      "sjv.pr2.d": "A concrete quote naming the responsible engineer and discipline lead.",
      "sjv.pr2.n": "Quote",
      "sjv.pr3.d": "Design, coordination and quality assurance.",
      "sjv.pr3.n": "Delivery",
      "sjv.pr4.d": "We follow the project through construction and handover.",
      "sjv.pr4.n": "Follow-up",
      "sjv.prosess_h2": "From inquiry to delivery.",
      "sjv.s01": "Three models",
      "sjv.s01tag": "How the market uses us",
      "sjv.s02": "Principles",
