      "sjv.title": "How we work · Builtly",
      "sw.bimv.badge": "Free",
      "sw.bimv.cta": "Open BIM Viewer — free",
      "sw.bimv.h": "Builtly BIM Viewer — free IFC viewer in the browser",
      "sw.bimv.mer": "More about BIM Viewer",
      "sw.bimv.p": "Drag in an IFC file and it opens — no installation, no licence, no company registration. Measure lengths and areas, cut sections, and read floor areas and residential units straight from the model. The file is parsed locally on your machine and never uploaded.",
      "sw.cta1": "Request a demo",
      "sw.cta2": "See the platform in detail",
      "sw.cta_h2": "See the software on one of your own projects.",
      "sw.cta_lede": "Request a demo on your own project data, or explore the platform and the toolbox in detail. Access and licensing are agreed per module.",
      "sw.cta_r2k": "Onboarding",
      "sw.cta_r2v": "Same day",
      "sw.cta_r3k": "Pilot",
      "sw.cta_r3v": "On your own project",
      "sw.desc": "Builtly's software is developed and used by consultants working on real engagements — maps, engineering, economics, sales, collaboration and finance.",
      "sw.eyebrow": "Builtly Software",
      "sw.fly1": "The consulting practice documents that the software works in reality.",
      "sw.fly2": "The software makes the consulting practice more efficient and scalable.",
      "sw.fly3": "Experience from engagements improves the products.",
      "sw.fly4": "Better products improve new engagements.",
      "sw.garanti_lenke": "Read more under Trust & security",
      "sw.garanti_mark": "Data guarantee",
      "sw.garanti_p": "Builtly Engineering has no access to software customers' projects unless the customer explicitly invites Builtly into the project or orders a consulting service. The customer owns the data, project data is never used to train models, and data and access are isolated per customer. Software customers' clients, project information and usage patterns are not used by Builtly's consulting practice for sales or competing bids.",
      "sw.h1": "Software developed through real projects.",
      "sw.kat1.d": "Builtly Maps, feasibility studies, climate risk and technical DD — the decision basis before the project exists.",
      "sw.kat1.h": "Maps & property analysis",
      "sw.kat1.l": "See Builtly Maps",
      "sw.kat2.d": "Geotechnics, structures, fire, acoustics, traffic, HSE, BREEAM and environment — the discipline modules that read and write BIM.",
      "sw.kat2.h": "Engineering & design",
      "sw.kat2.l": "See the discipline modules",
      "sw.kat3.d": "Tenders, quantities, area and yield, construction-loan control and credit basis — the project in numbers, on the same model.",
      "sw.kat3.h": "Quantities & economics",
      "sw.kat3.l": "See the economics modules",
      "sw.kat4.d": "Sales console, project websites, prospectus and prospect follow-up — sales pace measured against target, not gut feeling.",
      "sw.kat4.h": "Sales & marketing",
      "sw.kat4.l": "See the sales tools",
      "sw.kat5.d": "Project hotel/CDE with BIM in the browser, tender rooms, transmittals with receipts, site check-in — and Builtly Control for product documentation on the same project.",
      "sw.kat5.h": "Project & collaboration",
      "sw.kat5.l": "See the project hotel",
      "sw.kat6.d": "Construction-loan control, credit basis, climate risk and portfolio insight — structured decision support for lenders.",
      "sw.kat6.h": "Banking, finance & portfolio",
      "sw.kat6.l": "See the banking modules",
      "sw.kort_cta": "Explore",
      "sw.lede": "Builtly's software is developed and used by consultants who themselves work on ordinary engagements. That means the modules are built on real work processes, professional requirements and actual project deliverables — and can be used directly by clients, partners and other consultancies. This is deep tech — our own engines for BIM, regulation and computation.",
      "sw.s01": "Areas",
      "sw.s01h2": "The software area.",
      "sw.s01tag": "Six categories",
      "sw.s02": "Flywheel",
      "sw.s02h2": "Why it works.",
      "sw.s02tag": "Consulting and software reinforce each other",
