      "sw.tj_p": "Builtly also delivers complete consulting engagements in the same disciplines — with professional responsibility, coordination and follow-up.",
      "tj.aco.desc": "Builtly delivers complete consulting engagements in acoustics — building acoustics, room acoustics, noise calculations and documentation. Request a quote.",
      "tj.aco.fase1.d": "Noise assessment for the plan proposal.",
      "tj.aco.fase1.n": "Zoning",
      "tj.aco.fase2.d": "Acoustic premise document.",
      "tj.aco.fase2.n": "Permit",
      "tj.aco.fase3.d": "Detailing and discipline follow-up.",
      "tj.aco.fase3.n": "Detailed design",
      "tj.aco.fase4.d": "Control measurement and documentation.",
      "tj.aco.fase4.n": "Handover",
      "tj.aco.h1": "Acoustics",
      "tj.aco.lede": "Builtly takes responsibility for acoustic design — acoustic premises according to NS 8175, external noise assessment, building acoustics and room acoustics. Our consultants set the requirements early, follow them through detailing and document that the building delivers.",
      "tj.aco.lev1.d": "Requirements for airborne and impact sound, reverberation and technical noise for every room type — the premise the other disciplines design against.",
      "tj.aco.lev1.t": "Acoustic premise document",
      "tj.aco.lev2.d": "Noise calculations for zoning and permit, with facade measures and outdoor-area assessments.",
      "tj.aco.lev2.t": "External noise assessment",
      "tj.aco.lev3.d": "Design of separating constructions, detailing and flanking transmission in the detailed phase.",
      "tj.aco.lev3.t": "Building acoustics",
      "tj.aco.lev4.d": "Reverberation and speech-intelligibility calculations for teaching rooms, offices and common areas.",
      "tj.aco.lev4.t": "Room acoustics",
      "tj.aco.lev5.d": "Requirements and control of noise from building services, indoors and towards neighbours.",
      "tj.aco.lev5.t": "Technical noise",
      "tj.aco.lev6.d": "Control measurements and final documentation that the requirements are met.",
      "tj.aco.lev6.t": "Measurement and documentation",
      "tj.aco.ovd": "Building acoustics, room acoustics, noise calculations and documentation.",
      "tj.aco.ovh": "Acoustics",
      "tj.aco.sw_p": "Builtly's acoustics consultants use groundbreaking technology for analysis, drawing production and quality assurance. The same technology is available as software for clients and other consultancies.",
      "tj.aco.title": "Acoustics · Consulting engineers · Builtly",
      "tj.bhs.desc": "Builtly delivers complete consulting engagements in project & client support — design management, client advisory, procurement and quality assurance. Request a quote.",
