      "tj.bhs.fase4.n": "Construction",
      "tj.bhs.h1": "Project & client support",
      "tj.bhs.lede": "Builtly supports the client through the whole project — design management, procurement and tendering, quality assurance of deliverables and follow-up of progress, economy and handover.",
