      "tj.bhs.title": "Project & client support · Consulting engineers · Builtly",
      "tj.env.desc": "Builtly delivers complete consulting engagements in environment & sustainability — contaminated ground, environmental follow-up, reuse, emissions and nature. Request a quote.",
