      "tj.env.fase4.n": "Construction",
      "tj.env.h1": "Environment & sustainability",
      "tj.env.lede": "Builtly takes responsibility for environmental consulting — from environmental surveys and action plans for contaminated ground to environmental follow-up plans, reuse assessments and environmental certification. Our consultants set the environmental requirements and follow them up on site.",
      "tj.env.lev1.d": "Survey of hazardous substances in ground and existing buildings before demolition and excavation.",
