      "tj.env.lev2.d": "Action plan under the pollution regulations, with mass management and dialogue with the authorities.",
      "tj.env.lev2.t": "Contaminated-ground action plan",
      "tj.env.lev3.d": "Environmental requirements for the construction phase — waste, emissions, noise and nature — followed up with the contractor.",
      "tj.env.lev3.t": "Environmental follow-up plan",
      "tj.env.lev4.d": "Reuse survey and waste plan with sorting rates and documentation.",
      "tj.env.lev4.t": "Reuse and waste",
      "tj.env.lev5.d": "Pre-assessment and process support for BREEAM-NOR and similar schemes — honest assessments of secured level and forecast.",
      "tj.env.lev5.t": "Environmental certification",
      "tj.env.lev6.d": "Greenhouse-gas calculations for materials and operation as a decision basis in design.",
