      "tj.felles.tilbud_v": "Responsible engineer and discipline lead",
      "tj.fire.desc": "Builtly delivers complete consulting engagements in fire safety engineering — fire concept, escape strategy, fire drawings and follow-up through the project. Request a quote.",
      "tj.fire.fase1.d": "Fire concept as premise document.",
      "tj.fire.fase1.n": "Permit",
      "tj.fire.fase2.d": "Fire drawings and discipline clarifications.",
      "tj.fire.fase2.n": "Detailed design",
      "tj.fire.fase3.d": "Follow-up of the executing trades.",
      "tj.fire.fase3.n": "Construction",
      "tj.fire.fase4.d": "Control and final documentation.",
      "tj.fire.fase4.n": "Completion",
      "tj.fire.h1": "Fire safety engineering",
      "tj.fire.lede": "Builtly takes responsibility for fire safety engineering — fire concept according to the building regulations, fire drawings, escape strategy and follow-up of the executing disciplines. Our fire engineers take part in the design group, resolve deviations and follow the concept all the way to completion.",
      "tj.fire.lev1.d": "The fire-safety strategy for the project — fire and risk classes, load-bearing capacity, compartmentation and escape — as a premise for every discipline.",
      "tj.fire.lev1.t": "Fire concept",
      "tj.fire.lev2.d": "Fire compartments, escape routes, extinguishing equipment and door classes drawn on the plans with title block and legend, ready for control and use.",
      "tj.fire.lev2.t": "Fire drawings",
      "tj.fire.lev3.d": "Escape strategy and capacity assessments, including evacuation-time calculations where the concept requires analysis.",
      "tj.fire.lev3.t": "Escape analysis",
      "tj.fire.lev4.d": "Documentation of deviations from pre-accepted performance with comparative analysis.",
      "tj.fire.lev4.t": "Deviations and analysis",
      "tj.fire.lev5.d": "Access routes for the fire service, staging areas, extinguishing water and hydrants documented on the site plan.",
      "tj.fire.lev5.t": "Site fire drawing",
      "tj.fire.lev6.d": "Fire-safety follow-up in detailed design and construction, independent control where the project requires it.",
      "tj.fire.lev6.t": "Follow-up and control",
      "tj.fire.ovd": "Fire concept, escape strategy, fire drawings and follow-up through the project.",
      "tj.fire.ovh": "Fire safety engineering",
      "tj.fire.sw_p": "Builtly's fire safety engineering consultants use groundbreaking technology for analysis, drawing production and quality assurance. The same technology is available as software for clients and other consultancies.",
      "tj.fire.title": "Fire safety engineering · Consulting engineers · Builtly",
      "tj.geo.desc": "Builtly delivers complete consulting engagements in geotechnical engineering — ground conditions, foundations, stability, fem analysis and geotechnical reports. Request a quote.",
      "tj.geo.fase1.d": "Initial geotechnical assessment before the decision.",
      "tj.geo.fase1.n": "Site acquisition",
      "tj.geo.fase2.d": "Area stability and premises for the plan proposal.",
      "tj.geo.fase2.n": "Zoning",
      "tj.geo.fase3.d": "Factual report, foundations and detailed design.",
      "tj.geo.fase3.n": "Design",
      "tj.geo.fase4.d": "Follow-up, control and deviation assessment.",
      "tj.geo.fase4.n": "Construction",
      "tj.geo.h1": "Geotechnical engineering",
      "tj.geo.kontakt": "Stefan Ødegård · Head of Geotechnics",
      "tj.geo.lede": "Builtly takes responsibility for geotechnical design — from initial assessment of ground conditions to the geotechnical report, foundation concept and follow-up during construction. Our geotechnical engineers attend design meetings, make the professional judgements and act as responsible designer where agreed.",
      "tj.geo.lev1.d": "Initial assessment of ground conditions for site acquisition and zoning, and a geotechnical factual report as design basis for the building permit.",
      "tj.geo.lev1.t": "Geotechnical assessment and factual report",
      "tj.geo.lev2.d": "Selection and design of the foundation solution — shallow foundations, piles or compensated foundations — with settlement calculations.",
      "tj.geo.lev2.t": "Foundation concept",
      "tj.geo.lev3.d": "Stability calculations for excavations and slopes, and area-stability assessment in quick-clay zones according to NVE guideline 1/2019.",
      "tj.geo.lev3.t": "Stability and area stability",
      "tj.geo.lev4.d": "Advanced finite-element analysis of the interaction between excavation, structure and ground, with 3D models of stratification and pore pressure.",
      "tj.geo.lev4.t": "FEM analysis and 3D ground models",
      "tj.geo.lev5.d": "Responsible designer for geotechnics, in the responsibility class the project requires, with control and regulatory documentation.",
      "tj.geo.lev5.t": "Geotechnical design responsibility",
      "tj.geo.lev6.d": "On-site control of excavation and foundation works, assessment of deviations and supplementary ground investigations where needed.",
      "tj.geo.lev6.t": "Follow-up during construction",
      "tj.geo.ovd": "Ground conditions, foundations, stability, FEM analysis and geotechnical reports.",
      "tj.geo.ovh": "Geotechnical engineering",
      "tj.geo.sw_p": "Builtly's geotechnical engineering consultants use groundbreaking technology for analysis, drawing production and quality assurance. The same technology is available as software for clients and other consultancies.",
