      "trust.c20.body": "Builtly both sells software to consultancies and takes on consulting engagements of its own. The separation is therefore organisational and absolute: Builtly Engineering has no access to software customers' projects unless the customer explicitly invites Builtly into the project or orders a consulting service. Software customers' clients, project information and usage patterns are not used by Builtly's consulting practice for sales or competing bids.",
