      "ref.p3.h": "Brannkonsept, boligblokk — byggetrinn 2",
      "ref.p3.r": "Brannteknisk tegningsproduksjon med fagkontroll",
      "ref.p4.d": "Kvalitetssikring av en 2,7 millioner linjers ArchiCAD-eksport uten romobjekter: terrenget ble skilt fra boligarealet, enhetene målt av dørsignaler i skillevegger, og fellesmodellen føderert i nettleseren.",
      "ref.p4.f1k": "Prosjekttype",
