      "ref.p4.h": "Kystprosjekt — 153 leiligheter, samlemodell",
      "ref.p4.r": "Modellkontroll · samordning · enhetstelling",
      "ref.p5.d": "Landingsside på prosjektets eget domene, bla-bart prospekt, interessentregistrering med samtykke, meglervarsling og fredagsrapport til utbygger — salgsgrad og takt målt løpende.",
      "ref.p5.f1k": "Prosjekttype",
