      "ref.p5.r": "Salgskonsoll · prosjektnettside · prospekt",
      "ref.p6.d": "Anbudsgrunnlag bygget av prosjekthotellets mapper med frosne revisjoner, oversendt hver tilbyder med personlig lenke og kvittering — og anonym spørsmål/svar-runde med svar publisert til alle.",
