      "tj.fire.desc": "Builtly leverer komplette rådgiveroppdrag innen brannsikkerhet — brannkonsept, rømningsstrategi, branntegninger og oppfølging gjennom prosjektet. Be om tilbud.",
      "tj.fire.fase1.d": "Brannkonsept som premissdokument.",
      "tj.fire.fase1.n": "Rammesøknad",
      "tj.fire.fase2.d": "Branntegninger og fagavklaringer.",
      "tj.fire.fase2.n": "Detaljprosjekt",
      "tj.fire.fase3.d": "Oppfølging av utførende fag.",
      "tj.fire.fase3.n": "Utførelse",
      "tj.fire.fase4.d": "Kontroll og sluttdokumentasjon.",
      "tj.fire.fase4.n": "Ferdigattest",
      "tj.fire.h1": "Brannsikkerhet",
      "tj.fire.lede": "Builtly tar ansvar for brannteknisk prosjektering (RIBr) — brannkonsept etter TEK17 kapittel 11, branntegninger, rømningsstrategi og oppfølging av de utførende fagene. Våre brannrådgivere deltar i prosjekteringsgruppen, avklarer fravik og følger konseptet helt til ferdigattest.",
      "tj.fire.lev1.d": "Brannteknisk hovedgrep for tiltaket — brannklasser, risikoklasser, bæreevne, seksjonering og rømning — som premiss for alle fag.",
      "tj.fire.lev1.t": "Brannkonsept",
      "tj.fire.lev2.d": "Branncelleinndeling, rømningsveier, slokkeutstyr og dørklasser tegnet på planene med tittelfelt og symbolforklaring, klare for kontroll og bruk.",
      "tj.fire.lev2.t": "Branntegninger",
      "tj.fire.lev3.d": "Rømningsstrategi og kapasitetsvurderinger, inkludert beregning av rømningstider der konseptet krever analyse.",
      "tj.fire.lev3.t": "Rømningsanalyse",
      "tj.fire.lev4.d": "Dokumentasjon av fravik fra preaksepterte ytelser med komparativ analyse etter NS 3901.",
      "tj.fire.lev4.t": "Fravik og analyse",
      "tj.fire.lev5.d": "Innsatsveier, oppstillingsplasser, slokkevann og hydranter dokumentert på situasjonsplanen.",
      "tj.fire.lev5.t": "Utomhus branntegning",
      "tj.fire.lev6.d": "Brannteknisk oppfølging i detaljprosjektering og utførelse, uavhengig kontroll der prosjektet krever det.",
      "tj.fire.lev6.t": "Oppfølging og kontroll",
      "tj.fire.ovd": "Brannkonsept, rømningsstrategi, branntegninger og oppfølging gjennom prosjektet.",
      "tj.fire.ovh": "Brannsikkerhet",
      "tj.fire.sw_p": "Builtlys brannsikkerhet-rådgivere benytter banebrytende teknologi til analyser, tegningsproduksjon og kvalitetssikring. Den samme teknologien er tilgjengelig som software for kunder og andre rådgivermiljøer.",
      "tj.fire.title": "Brannsikkerhet · Rådgivende ingeniører · Builtly",
      "tj.geo.desc": "Builtly leverer komplette rådgiveroppdrag innen geoteknikk — grunnforhold, fundamentering, stabilitet, fem-analyser og geotekniske rapporter. Be om tilbud.",
      "tj.geo.fase1.d": "Innledende geoteknisk vurdering før beslutning.",
      "tj.geo.fase1.n": "Tomtekjøp",
      "tj.geo.fase2.d": "Områdestabilitet og premisser for planforslaget.",
      "tj.geo.fase2.n": "Regulering",
      "tj.geo.fase3.d": "Datarapport, fundamentering og prosjektering.",
      "tj.geo.fase3.n": "Prosjektering",
      "tj.geo.fase4.d": "Oppfølging, kontroll og avviksvurdering.",
      "tj.geo.fase4.n": "Utførelse",
      "tj.geo.h1": "Geoteknikk",
      "tj.geo.kontakt": "Stefan Ødegård · Head of Geotechnics",
      "tj.geo.lede": "Builtly tar ansvar for geoteknisk prosjektering — fra innledende vurdering av grunnforhold til geoteknisk rapport, fundamenteringskonsept og oppfølging i byggetid. Våre geoteknikere deltar i prosjekteringsmøter, gjør de faglige vurderingene og står som ansvarlig prosjekterende der det er avtalt.",
      "tj.geo.lev1.d": "Innledende vurdering av grunnforhold for tomtekjøp og regulering, og geoteknisk datarapport som prosjekteringsgrunnlag for rammesøknad.",
      "tj.geo.lev1.t": "Geoteknisk vurdering og datarapport",
      "tj.geo.lev2.d": "Valg og dimensjonering av fundamenteringsløsning — direktefundamentering, peler eller kompensert fundamentering — med setningsberegninger.",
      "tj.geo.lev2.t": "Fundamenteringskonsept",
      "tj.geo.lev3.d": "Stabilitetsberegninger for byggegrop og skråninger, og utredning av områdestabilitet i kvikkleiresoner etter NVEs veileder 1/2019.",
      "tj.geo.lev3.t": "Stabilitet og områdestabilitet",
      "tj.geo.lev4.d": "Avanserte elementanalyser av samvirke mellom byggegrop, konstruksjon og grunn, med 3D-modeller av lagdeling og poretrykk.",
      "tj.geo.lev4.t": "FEM-analyser og 3D-grunnmodeller",
      "tj.geo.lev5.d": "Ansvarlig prosjekterende for geoteknikk i tiltaksklasse etter kompetanse og avtale, med kontroll og myndighetsdokumentasjon.",
      "tj.geo.lev5.t": "Geoteknisk prosjektering (PRO)",
      "tj.geo.lev6.d": "Kontroll av utgraving og fundamentering på plassen, vurdering av avvik og supplerende grunnundersøkelser ved behov.",
      "tj.geo.lev6.t": "Oppfølging i byggetid",
      "tj.geo.ovd": "Grunnforhold, fundamentering, stabilitet, FEM-analyser og geotekniske rapporter.",
      "tj.geo.ovh": "Geoteknikk",
      "tj.geo.sw_p": "Builtlys geoteknikk-rådgivere benytter banebrytende teknologi til analyser, tegningsproduksjon og kvalitetssikring. Den samme teknologien er tilgjengelig som software for kunder og andre rådgivermiljøer.",
      "tj.geo.title": "Geoteknikk · Rådgivende ingeniører · Builtly",
      "tj.ov.cta2": "Slik jobber vi",
      "tj.ov.desc": "Builtly leverer komplette rådgiveroppdrag innen geoteknikk, konstruksjon, brann, akustikk, miljø, trafikk, SHA og teknisk due diligence.",
      "tj.ov.h1": "Rådgivende ingeniører.",
      "tj.ov.kort_cta": "Se tjenesten",
      "tj.ov.lede": "Builtly tar ansvar for ordinære rådgiveroppdrag. Kunden kjøper en vanlig rådgiverleveranse: våre ingeniører deltar i møter, prosjekterer, gjør faglige vurderinger, koordinerer, kvalitetssikrer, signerer og følger opp prosjektet. Du behøver ikke kjøpe software eller endre arbeidsmåte.",
      "tj.ov.s01": "Fagområder",
