      "tj.sha.h1": "SHA",
      "tj.sha.lede": "Builtly tar ansvar for SHA-arbeidet etter byggherreforskriften — SHA-plan, risikokartlegging i prosjekteringen og koordinering i både prosjekterings- og utførelsesfasen (KP/KU).",
