      "tj.sha.title": "SHA · Rådgivende ingeniører · Builtly",
      "tj.str.desc": "Builtly leverer komplette rådgiveroppdrag innen konstruksjon — bæresystemer, dimensjonering, konstruksjonssikkerhet, tegninger og beregningsgrunnlag. Be om tilbud.",
      "tj.str.fase1.d": "Bæresystem, spennvidder og kostnadsdrivere.",
      "tj.str.fase1.n": "Tidligfase",
      "tj.str.fase2.d": "Konstruksjonsteknisk premissdokument.",
      "tj.str.fase2.n": "Rammesøknad",
      "tj.str.fase3.d": "Dimensjonering, tegninger, mengder.",
      "tj.str.fase3.n": "Detaljprosjekt",
      "tj.str.fase4.d": "Oppfølging, kontroll og as-built.",
      "tj.str.fase4.n": "Utførelse",
      "tj.str.h1": "Konstruksjon",
      "tj.str.lede": "Builtly tar ansvar for konstruksjonsteknisk prosjektering (RIB) — bæresystem, dimensjonering etter Eurokodene, tegninger og beregningsgrunnlag. Våre ingeniører prosjekterer, koordinerer mot arkitekt og øvrige fag, kvalitetssikrer og følger prosjektet gjennom utførelsen.",
      "tj.str.lev1.d": "Valg av bæresystem i tidligfase — spennvidder, stabilitet og føringsveier — som premiss for arkitektur og økonomi.",
      "tj.str.lev1.t": "Bæresystem og konsept",
      "tj.str.lev2.d": "Statiske beregninger av betong-, stål- og trekonstruksjoner etter NS-EN 1990–1999 med nasjonale tillegg.",
      "tj.str.lev2.t": "Dimensjonering etter Eurokodene",
      "tj.str.lev3.d": "Sporbart beregningsgrunnlag, arbeidstegninger og armeringstegninger — levert som redigerbare fagformater (IFC, DWG/DXF, PDF).",
      "tj.str.lev3.t": "Beregningsrapporter og tegninger",
      "tj.str.lev4.d": "Kontroll av arkitektmodellen mot tegninger, fagmodell som IFC og avvik som BCF — modellen prosjekteres på, ikke rundt.",
      "tj.str.lev4.t": "BIM-kontroll og samordning",
      "tj.str.lev5.d": "Mengdeuttak med sporbarhet til kilde, som grunnlag for kalkyle og kontrahering.",
      "tj.str.lev5.t": "Mengder etter NS 3420",
      "tj.str.lev6.d": "Uavhengig kontroll av prosjektering der prosjektet krever det, og oppfølging av utførelsen.",
      "tj.str.lev6.t": "Kontroll og oppfølging",
      "tj.str.ovd": "Bæresystemer, dimensjonering, konstruksjonssikkerhet, tegninger og beregningsgrunnlag.",
      "tj.str.ovh": "Konstruksjon",
      "tj.str.sw_p": "Builtlys konstruksjon-rådgivere benytter banebrytende teknologi til analyser, tegningsproduksjon og kvalitetssikring. Den samme teknologien er tilgjengelig som software for kunder og andre rådgivermiljøer.",
      "tj.str.title": "Konstruksjon · Rådgivende ingeniører · Builtly",
      "tj.tdd.desc": "Builtly leverer komplette rådgiveroppdrag innen teknisk due diligence — teknisk gjennomgang av eiendom ved kjøp, salg og finansiering. Be om tilbud.",
