      "tj.tdd.fase4.d": "Verifikasjon og restpunkter.",
      "tj.tdd.fase4.n": "Overtakelse",
      "tj.tdd.h1": "Teknisk due diligence",
      "tj.tdd.lede": "Builtly tar ansvar for teknisk due diligence i transaksjoner — tilstandsvurdering, kostnadsestimat for vedlikeholdsetterslep, miljø- og klimarisiko og strukturert gjennomgang av datarommet. Leveransen er et beslutningsgrunnlag kjøper, selger og bank kan handle på.",
      "tj.tdd.lev1.d": "Systematisk gjennomgang av byggets tekniske tilstand etter NS 3424, med tilstandsgrader og restlevetid.",
      "tj.tdd.lev1.t": "Tilstandsvurdering",
      "tj.tdd.lev2.d": "Prissatt vedlikeholdsetterslep og investeringsbehov fordelt over tid — tallene forhandlingen bruker.",
      "tj.tdd.lev2.t": "Kostnadsestimat",
      "tj.tdd.lev3.d": "Screening av forurensning, flom, havnivå, vind og skred — mot EU-taksonomiens krav der det er relevant.",
      "tj.tdd.lev3.t": "Miljø- og klimarisiko",
      "tj.tdd.lev4.d": "Strukturert gjennomgang av teknisk dokumentasjon i datarommet, med funn, hull og røde flagg.",
      "tj.tdd.lev4.t": "Datarom-gjennomgang",
      "tj.tdd.ovd": "Teknisk gjennomgang av eiendom ved kjøp, salg og finansiering.",
      "tj.tdd.ovh": "Teknisk due diligence",
      "tj.tdd.sw_p": "Builtlys teknisk due diligence-rådgivere benytter banebrytende teknologi til analyser, tegningsproduksjon og kvalitetssikring. Den samme teknologien er tilgjengelig som software for kunder og andre rådgivermiljøer.",
      "tj.tdd.title": "Teknisk due diligence · Rådgivende ingeniører · Builtly",
      "tj.tra.desc": "Builtly leverer komplette rådgiveroppdrag innen trafikk — trafikkanalyser, parkering, byggeplasstrafikk og mobilitet. Be om tilbud.",
      "tj.tra.fase1.d": "Overordnet vurdering av adkomst.",
      "tj.tra.fase1.n": "Tidligfase",
      "tj.tra.fase2.d": "Trafikkanalyse til planforslaget.",
      "tj.tra.fase2.n": "Regulering",
      "tj.tra.fase3.d": "Parkering, sikt og detaljer.",
      "tj.tra.fase3.n": "Prosjektering",
      "tj.tra.fase4.d": "Byggeplasstrafikk og faseplaner.",
      "tj.tra.fase4.n": "Utførelse",
      "tj.tra.h1": "Trafikk",
      "tj.tra.lede": "Builtly tar ansvar for trafikkfaglige utredninger — trafikkanalyse til regulering, parkeringsdekning, trafikksikkerhet og anleggslogistikk. Leveransene er skrevet for planmyndigheten og prosjekteringsgruppen, ikke for skuffen.",
      "tj.tra.lev1.d": "Turproduksjon, kapasitet i kryss og belastning på omkringliggende nett — grunnlaget planmyndigheten spør etter.",
      "tj.tra.lev1.t": "Trafikkanalyse",
      "tj.tra.lev2.d": "Parkeringsdekning etter kommunal norm, sykkelparkering og mobilitetsplan.",
      "tj.tra.lev2.t": "Parkering og mobilitet",
      "tj.tra.lev3.d": "Siktanalyser, myke trafikanter og skolevei — dokumentert mot håndbøkene.",
      "tj.tra.lev3.t": "Trafikksikkerhet",
      "tj.tra.lev4.d": "Anleggslogistikk, riggplan-premisser og faseplaner for trafikkavvikling i byggetiden.",
      "tj.tra.lev4.t": "Byggeplasstrafikk",
      "tj.tra.ovd": "Trafikkanalyser, parkering, byggeplasstrafikk og mobilitet.",
      "tj.tra.ovh": "Trafikk",
      "tj.tra.sw_p": "Builtlys trafikk-rådgivere benytter banebrytende teknologi til analyser, tegningsproduksjon og kvalitetssikring. Den samme teknologien er tilgjengelig som software for kunder og andre rådgivermiljøer.",
      "tj.tra.title": "Trafikk · Rådgivende ingeniører · Builtly",
      "trust.c20.body": "Builtly både selger software til rådgivermiljøer og tar egne rådgiveroppdrag. Derfor er skillet organisatorisk og absolutt: Builtly Engineering har ikke tilgang til softwarekunders prosjekter uten at kunden uttrykkelig inviterer Builtly inn i prosjektet eller bestiller en rådgivertjeneste. Softwarekunders kunder, prosjektinformasjon og bruksmønstre benyttes ikke av Builtlys rådgivningsvirksomhet til salg eller konkurrerende tilbud.",
      "trust.c20.h": "Builtly Engineering ser ikke softwarekunders prosjekter.",
      "trust.smark.guarantee": "Organisatorisk garanti",
