  "ns.geoteknikk.002": "Geotechnics.<br><span class=\"aks\">Ground first.</span>",
  "ns.geoteknikk.003": "Ground conditions, foundations, stability and reporting. From the first assessment of the site to design.",
  "ns.geoteknikk.004": "<a class=\"btn\" href=\"/contact\">Send an enquiry <span aria-hidden=\"true\">→</span></a><a class=\"btn btn-ghost\" href=\"/uavhengig-kontroll\">Independent control</a>",
  "ns.geoteknikk.005": "<span class=\"k\">Deliverable</span><span class=\"v\">Consulting and design</span>",
  "ns.geoteknikk.006": "<span class=\"k\">Price</span><span class=\"v\">Fixed price for the deliverable</span>",
