  "ns.geoteknikk.009": "<span>What we deliver</span>",
  "ns.geoteknikk.010": "This is what we do in geotechnics.",
  "ns.geoteknikk.011": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Assessment of ground conditions.</b> Initial assessment before site purchase and zoning.</span>",
  "ns.geoteknikk.012": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Geotechnical data report.</b> Field data and lab results from the ground investigation, compiled and presented.</span>",
