  "ns.geoteknikk.014": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Stability.</b> Excavations and slopes.</span>",
  "ns.geoteknikk.015": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Area stability.</b> Assessment in quick clay zones according to NVE guideline 1/2019.</span>",
  "ns.geoteknikk.016": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Geotechnical design.</b> Designer in geotechnics, with the documentation the municipality needs.</span>",
  "ns.geoteknikk.017": "<span class=\"t\">How we work</span><span class=\"strek\"></span><span>Built for AI from day one</span>",
  "ns.geoteknikk.018": "The agents read. The tools calculate. The engineer signs.",
  "ns.geoteknikk.019": "In geotechnics, the agents read field data and lab results, and the tools interpret the soundings and give the numbers. The geotechnical engineer checks the assumptions and interpretations, and signs.",
