  "ns.konstruksjon.001": "<a class=\"t\" href=\"/tjenester\">Consulting</a><span class=\"strek\"></span><span>RIB</span>",
  "ns.konstruksjon.002": "Structural engineering.<br><span class=\"aks\">In every phase.</span>",
  "ns.konstruksjon.003": "Load-bearing systems, dimensioning and structural assessments, from the first sketches to a fully designed building. We also carry out independent control of structural safety.",
  "ns.konstruksjon.004": "<a class=\"btn\" href=\"/contact\">Send an enquiry <span aria-hidden=\"true\">→</span></a><a class=\"btn btn-ghost\" href=\"/uavhengig-kontroll\">Independent control</a>",
  "ns.konstruksjon.005": "<span class=\"k\">Deliverable</span><span class=\"v\">Consulting and design</span>",
  "ns.konstruksjon.006": "<span class=\"k\">Price</span><span class=\"v\">Fixed price for the deliverable</span>",
  "ns.konstruksjon.007": "<span class=\"k\">Independent control</span><span class=\"v\">NOK 20,000 per discipline</span>",
  "ns.konstruksjon.008": "<span class=\"k\">Reply to enquiry</span><span class=\"v\">Within two working days</span>",
  "ns.konstruksjon.009": "<span>What we deliver</span>",
  "ns.konstruksjon.010": "This is what we do in structural engineering.",
  "ns.konstruksjon.011": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Load-bearing system and concept.</b> Spans, stability and load paths as a premise for the architecture.</span>",
  "ns.konstruksjon.012": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Dimensioning to the Eurocodes.</b> Concrete, steel and timber structures to NS-EN 1990–1999.</span>",
  "ns.konstruksjon.013": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Calculations and reports.</b> Traceable calculation basis for every structural element.</span>",
  "ns.konstruksjon.014": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Drawings and model.</b> Structural drawings and discipline model for the design team.</span>",
  "ns.konstruksjon.015": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Design of structural safety.</b> Designer in structural engineering, with the documentation the municipality needs.</span>",
  "ns.konstruksjon.016": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Structural assessments.</b> Memos on solutions, changes and existing structures.</span>",
  "ns.konstruksjon.017": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Independent control of structural safety.</b> Consequence class 2, fixed price per discipline.</span>",
  "ns.konstruksjon.018": "<span class=\"t\">How we work</span><span class=\"strek\"></span><span>Built for AI from day one</span>",
  "ns.konstruksjon.019": "The agents read. The tools calculate. The engineer signs.",
