  "ns.maps.001": "<span class=\"ruten\">1</span>Maps",
  "ns.maps.002": "Everything about the property.<br><span class=\"aks\">In one place.</span>",
  "ns.maps.003": "Look up an address, a cadastral unit (gnr/bnr) or a company. Owner, zoning, risk and market are in one property card, and you can take the property straight on to a mulighetsstudie.",
  "ns.maps.004": "<a class=\"btn\" href=\"/contact\">Book a walkthrough <span aria-hidden=\"true\">→</span></a><a class=\"btn btn-ghost\" href=\"/software\">See all four products</a>",
  "ns.maps.005": "Search",
  "ns.maps.006": "Address, gnr/bnr, owner or company.",
  "ns.maps.007": "The property card",
  "ns.maps.008": "Cadastral data, area, buildings, registered owner and energy certificate.",
  "ns.maps.009": "Map layers",
  "ns.maps.010": "Zoning, flood, landslide, quick clay, radon and noise on the same map.",
  "ns.maps.011": "Owner and market",
  "ns.maps.012": "Accounts, group structure and a value indication with a range.",
  "ns.maps.013": "Report",
  "ns.maps.014": "Property, area or company report as PDF.",
  "ns.maps.015": "<span class=\"t\">01 · Find</span><span class=\"strek\"></span><span>What it looks like</span>",
  "ns.maps.016": "Maps in use.",
  "ns.maps.017": "For developers, property advisers, estate agents and architects.",
  "ns.maps.018": "The screenshot is from Maps, with a property in Trondheim.",
  "ns.maps.035": "<span>What you get</span>",
  "ns.maps.036": "Concrete, from day one.",
  "ns.maps.037": "The property card",
  "ns.maps.038": "Cadastral data and plot area, buildings with BYA and BRA, registered owner, energy certificate and planning basis for the property.",
  "ns.maps.039": "Over 60 map layers",
  "ns.maps.040": "Zoning, NVE's flood and landslide zones, quick clay, NGU's superficial deposits and radon, cultural heritage and noise. From public sources, with a legend.",
  "ns.maps.041": "Owner and company",
  "ns.maps.042": "Accounts and key figures, group structure and which properties the company owns.",
  "ns.maps.043": "Value indication",
  "ns.maps.044": "A range with confidence and method, calculated from registered sales and market data. It is an indication and not a valuation.",
  "ns.maps.045": "Radars and alerts",
  "ns.maps.046": "Find undeveloped sites by area and zoning. Follow properties, owners and municipalities, and get alerts on bankruptcies and tenders.",
  "ns.maps.047": "Reports",
  "ns.maps.048": "Property, area, company, portfolio and climate risk reports, ready to send on as PDF.",
  "ns.maps.049": "<span class=\"t\">Without and with Maps</span>",
  "ns.maps.050": "Five websites become one search.",
  "ns.maps.051": "Today",
  "ns.maps.052": "How it is often done",
  "ns.maps.053": "Look up property and owner in Se eiendom and in the Brønnøysund registers.",
  "ns.maps.054": "Find the zoning plan in the municipality's planning portal and read the provisions.",
  "ns.maps.055": "Check flood, landslide and quick clay at NVE, and superficial deposits and radon at NGU.",
  "ns.maps.056": "Look for building applications in public mail records and eInnsyn.",
  "ns.maps.057": "Put together the area profile from SSB in a spreadsheet.",
  "ns.maps.058": "<span>Result</span><b>Five websites, one property at a time</b>",
  "ns.maps.059": "With Maps",
  "ns.maps.060": "How you do it here",
  "ns.maps.061": "Search for the address or gnr/bnr.",
  "ns.maps.062": "The property card shows owner, plan and risk.",
  "ns.maps.063": "Switch on the map layers you need.",
  "ns.maps.064": "The cases are in the same card.",
  "ns.maps.065": "Print the property or area report.",
  "ns.maps.066": "<span>Result</span><b>One search</b>",
  "ns.maps.067": "The property card with owner and area applies to Norway. In Sweden, Maps has map layers and area statistics.",
  "ns.maps.068": "<span class=\"t\">Tailored to you</span><span class=\"strek\"></span><span>Get in touch for a walkthrough</span>",
  "ns.maps.069": "See Maps on your own project.",
  "ns.maps.070": "We start from an area you know, and show how you find and prioritise the properties there. We set up the product with your data and users, and the price is agreed based on what you need.",
  "ns.maps.071": "<a class=\"btn\" href=\"/contact\">Book a walkthrough <span aria-hidden=\"true\">→</span></a>",
  "ns.maps.072": "Software: <b>Olav Aukan Stenersen</b> <span class=\"mono\">+47 907 00 719</span> · <b>Sofie Thire</b> <span class=\"mono\">+47 912 42 705</span>",
