  "ns.maps.bilde.alt": "Maps: a property in the 3D map with the property card and property details with value estimate, key data, zoning plan and risk profile",
  "ns.mulighetsstudie.001": "<span class=\"ruten\">2</span>Mulighetsstudie",
  "ns.mulighetsstudie.002": "What can the site take?<br><span class=\"aks\">Three concepts, calculated.</span>",
  "ns.mulighetsstudie.003": "From property to decision basis: zoning, development alternatives with areas, sun and shadow, and project economics, with measured and traceable figures.",
  "ns.mulighetsstudie.004": "<a class=\"btn\" href=\"/contact\">Book a walkthrough <span aria-hidden=\"true\">→</span></a><a class=\"btn btn-ghost\" href=\"/software\">See all four products</a>",
  "ns.mulighetsstudie.005": "Property",
  "ns.mulighetsstudie.006": "Gnr/bnr. Site, zoning, neighbours and terrain are retrieved.",
  "ns.mulighetsstudie.007": "Buildable area",
  "ns.mulighetsstudie.008": "Building limits and obstacles are drawn on the orthophoto.",
  "ns.mulighetsstudie.009": "Alternatives",
  "ns.mulighetsstudie.010": "Three concepts with area, homes, sun and economics.",
  "ns.mulighetsstudie.011": "Recommendation",
  "ns.mulighetsstudie.012": "Ranked by an open scoring model you can adjust.",
  "ns.mulighetsstudie.013": "Deliverable",
  "ns.mulighetsstudie.014": "A3 report and a simple teaser as PDF.",
  "ns.mulighetsstudie.015": "<span class=\"t\">02 · Assess</span><span class=\"strek\"></span><span>What it looks like</span>",
  "ns.mulighetsstudie.016": "Mulighetsstudie in use.",
  "ns.mulighetsstudie.017": "For property developers, property owners and architects.",
  "ns.mulighetsstudie.018": "The screenshot is from Mulighetsstudie, with a demo project in Trondheim.",
  "ns.mulighetsstudie.036": "<span>What you get</span>",
  "ns.mulighetsstudie.037": "Concrete, from day one.",
  "ns.mulighetsstudie.038": "The A3 report",
  "ns.mulighetsstudie.039": "Zoning, buildable area, the alternatives with plan and key figures, area accounts with BTA, BRA and BRA-i, sun and shadow, and land value.",
  "ns.mulighetsstudie.040": "Three concepts on the same site",
  "ns.mulighetsstudie.041": "Linear, block with courtyard and clusters, built from slab blocks, point blocks, perimeter blocks and terraced houses. The number of homes follows from the area.",
  "ns.mulighetsstudie.042": "Open ranking",
  "ns.mulighetsstudie.043": "The default weights are in the report: architecture 50, goal fulfilment 20, outdoor space 14, sun 10 and BYA 6. You can change them.",
  "ns.mulighetsstudie.044": "Sun and shadow",
  "ns.mulighetsstudie.045": "Shadows for the spring equinox, summer and winter at several times of day, and sun hours on the outdoor space.",
  "ns.mulighetsstudie.046": "Land value",
  "ns.mulighetsstudie.047": "Residual land value with all assumptions visible. An early-stage estimate, not a valuation.",
  "ns.mulighetsstudie.048": "Commercial too",
  "ns.mulighetsstudie.049": "Offices, warehousing and logistics, hotels and retail, with their own floor heights, building depths and parking norms.",
  "ns.mulighetsstudie.050": "<span class=\"t\">Without and with Mulighetsstudie</span>",
  "ns.mulighetsstudie.051": "Five steps in one flow.",
  "ns.mulighetsstudie.052": "Today",
  "ns.mulighetsstudie.053": "How it is often done",
  "ns.mulighetsstudie.054": "Get the site and area from the cadastre.",
  "ns.mulighetsstudie.055": "Read the zoning provisions for BYA, storeys and height.",
  "ns.mulighetsstudie.056": "Draw building limits and restriction zones in CAD.",
  "ns.mulighetsstudie.057": "Build volume studies by hand, one alternative at a time.",
  "ns.mulighetsstudie.058": "Calculate areas, sun and shadow, and land value in separate tools.",
  "ns.mulighetsstudie.059": "<span>Tools</span><b>Several, often with an architect and a consultant</b>",
  "ns.mulighetsstudie.060": "With Mulighetsstudie",
  "ns.mulighetsstudie.061": "How you do it here",
  "ns.mulighetsstudie.062": "Select the site by gnr/bnr.",
  "ns.mulighetsstudie.063": "Zoning, neighbours and terrain are retrieved.",
  "ns.mulighetsstudie.064": "Draw what cannot be built on, directly on the orthophoto.",
  "ns.mulighetsstudie.065": "Three concepts are built and ranked.",
  "ns.mulighetsstudie.066": "Download the A3 report and the teaser.",
  "ns.mulighetsstudie.067": "<span>Tools</span><b>One, with an A3 report at the end</b>",
  "ns.mulighetsstudie.068": "The study is not design, not a daylight calculation under TEK17 and not a valuation.",
  "ns.mulighetsstudie.069": "<span class=\"t\">Tailored to you</span><span class=\"strek\"></span><span>Get in touch for a walkthrough</span>",
  "ns.mulighetsstudie.070": "See Mulighetsstudie on your own project.",
  "ns.mulighetsstudie.071": "Pick a property you are already considering, and we will show three concepts on the same site. We set up the product with your data and users, and the price is agreed based on what you need.",
  "ns.mulighetsstudie.072": "<a class=\"btn\" href=\"/contact\">Book a walkthrough <span aria-hidden=\"true\">→</span></a>",
