  "ns.geoteknikk.001": "<a class=\"t\" href=\"/tjenester\">Rådgivning</a><span class=\"strek\"></span><span>RIG</span>",
  "ns.geoteknikk.002": "Geoteknikk.<br><span class=\"aks\">Grunnen først.</span>",
  "ns.geoteknikk.003": "Grunnforhold, fundamentering, stabilitet og rapportering. Fra den første vurderingen av tomta til prosjektering.",
  "ns.geoteknikk.004": "<a class=\"btn\" href=\"/contact\">Send en forespørsel <span aria-hidden=\"true\">→</span></a><a class=\"btn btn-ghost\" href=\"/uavhengig-kontroll\">Uavhengig kontroll</a>",
  "ns.geoteknikk.005": "<span class=\"k\">Leveranse</span><span class=\"v\">Rådgivning og prosjektering</span>",
  "ns.geoteknikk.006": "<span class=\"k\">Pris</span><span class=\"v\">Fast pris for leveransen</span>",
  "ns.geoteknikk.007": "<span class=\"k\">Uavhengig kontroll</span><span class=\"v\">20 000 kr per fag</span>",
  "ns.geoteknikk.008": "<span class=\"k\">Svar på forespørsel</span><span class=\"v\">Innen to virkedager</span>",
  "ns.geoteknikk.009": "<span>Det vi leverer</span>",
  "ns.geoteknikk.010": "Dette gjør vi i geoteknikk.",
  "ns.geoteknikk.011": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Vurdering av grunnforhold.</b> Innledende vurdering før tomtekjøp og regulering.</span>",
  "ns.geoteknikk.012": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Geoteknisk datarapport.</b> Feltdata og labresultater fra grunnundersøkelsen, samlet og presentert.</span>",
  "ns.geoteknikk.013": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Fundamentering.</b> Valg og dimensjonering av løsning, med setningsberegninger.</span>",
  "ns.geoteknikk.014": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Stabilitet.</b> Byggegrop og skråninger.</span>",
  "ns.geoteknikk.015": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Områdestabilitet.</b> Utredning i kvikkleiresoner etter NVEs veileder 1/2019.</span>",
  "ns.geoteknikk.016": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Geoteknisk prosjektering.</b> Prosjekterende i geoteknikk, med dokumentasjonen kommunen trenger.</span>",
  "ns.geoteknikk.017": "<span class=\"t\">Slik jobber vi</span><span class=\"strek\"></span><span>Bygget for KI fra første dag</span>",
  "ns.geoteknikk.018": "Agentene leser. Verktøyene beregner. Ingeniøren signerer.",
  "ns.geoteknikk.019": "I geoteknikk leser agentene feltdata og labresultater, og verktøyene tolker sonderingene og gir tallene. Geoteknikeren kontrollerer forutsetningene og tolkningene, og signerer.",
  "ns.geoteknikk.020": "Se arbeidsmåten <span aria-hidden=\"true\">→</span>",
  "ns.geoteknikk.021": "<span>Når i prosjektet</span>",
  "ns.geoteknikk.022": "Fra tidligfase til ferdig bygg.",
