  "ns.geoteknikk.024": "Innledende vurdering før beslutning.",
  "ns.geoteknikk.025": "Regulering",
  "ns.geoteknikk.026": "Områdestabilitet og premisser for planen.",
  "ns.geoteknikk.027": "Prosjektering",
  "ns.geoteknikk.028": "Datarapport, fundamentering og prosjektering.",
  "ns.geoteknikk.029": "Byggetid",
  "ns.geoteknikk.030": "Vurdering av avvik og endringer.",
  "ns.geoteknikk.031": "<span class=\"t\">Kontakt</span>",
  "ns.geoteknikk.032": "Ta kontakt.",
  "ns.geoteknikk.033": "Stefan Ødegård",
