  "ns.geoteknikk.036": "stefan@builtly.ai",
  "ns.geoteknikk._beskrivelse": "Geoteknisk rådgivning og prosjektering: grunnforhold, datarapport, fundamentering, stabilitet og områdestabilitet. Svar på forespørsel innen to virkedager.",
  "ns.geoteknikk._tittel": "Geoteknikk · Rådgivning · Builtly",
  "ns.konstruksjon.001": "<a class=\"t\" href=\"/tjenester\">Rådgivning</a><span class=\"strek\"></span><span>RIB</span>",
