  "ns.konstruksjon.003": "Bæresystem, dimensjonering og konstruktive vurderinger, fra de første skissene til ferdig prosjektert bygg. Vi tar også uavhengig kontroll av konstruksjonssikkerheten.",
  "ns.konstruksjon.004": "<a class=\"btn\" href=\"/contact\">Send en forespørsel <span aria-hidden=\"true\">→</span></a><a class=\"btn btn-ghost\" href=\"/uavhengig-kontroll\">Uavhengig kontroll</a>",
