  "ns.konstruksjon.009": "<span>Det vi leverer</span>",
  "ns.konstruksjon.010": "Dette gjør vi i konstruksjon.",
  "ns.konstruksjon.011": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Bæresystem og konsept.</b> Spennvidder, stabilitet og føringsveier som premiss for arkitekturen.</span>",
  "ns.konstruksjon.012": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Dimensjonering etter Eurokodene.</b> Betong-, stål- og trekonstruksjoner etter NS-EN 1990–1999.</span>",
  "ns.konstruksjon.013": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Beregninger og rapporter.</b> Sporbart beregningsgrunnlag for hver konstruksjonsdel.</span>",
  "ns.konstruksjon.014": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Tegninger og modell.</b> Konstruksjonstegninger og fagmodell til prosjekteringsgruppen.</span>",
  "ns.konstruksjon.015": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Prosjektering av konstruksjonssikkerhet.</b> Prosjekterende i konstruksjon, med dokumentasjonen kommunen trenger.</span>",
  "ns.konstruksjon.016": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Konstruktive vurderinger.</b> Notater om løsninger, endringer og eksisterende konstruksjoner.</span>",
  "ns.konstruksjon.017": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span><b>Uavhengig kontroll av konstruksjonssikkerhet.</b> Tiltaksklasse 2, fast pris per fag.</span>",
  "ns.konstruksjon.018": "<span class=\"t\">Slik jobber vi</span><span class=\"strek\"></span><span>Bygget for KI fra første dag</span>",
