  "ns.software.024": "§ 01 · Finn",
  "ns.software.025": "Maps",
  "ns.software.026": "Alt om eiendommen, på ett sted. Søk opp en adresse og se eier, regulering, risiko og marked i ett eiendomskort.",
  "ns.software.027": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Matrikkel, areal, bygg og hjemmelshaver</span>",
  "ns.software.028": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Over 60 kartlag fra NVE, NGU, DiBK og flere</span>",
  "ns.software.029": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Eier, regnskap og verdiindikasjon med spenn</span>",
  "ns.software.030": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Eiendoms- og områderapport som PDF</span>",
  "ns.software.031": "Les mer om Maps <span aria-hidden=\"true\">→</span>",
  "ns.software.048": "§ 02 · Vurder",
  "ns.software.049": "Mulighetsstudie",
  "ns.software.050": "Hva tåler tomten? Tre konsepter på samme tomt, med arealer, boliger, sol og skygge og tomteverdi.",
  "ns.software.051": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Tomt, regulering, naboer og terreng hentes inn</span>",
  "ns.software.052": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Byggegrenser og hindringer tegnes på ortofoto</span>",
  "ns.software.053": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Rangert etter en åpen poengmodell</span>",
  "ns.software.054": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>A3-rapport til styret og banken, og en teaser</span>",
  "ns.software.055": "Les mer om Mulighetsstudie <span aria-hidden=\"true\">→</span>",
  "ns.software.073": "§ 03 · Utvikle",
  "ns.software.074": "Prosjekthotell",
  "ns.software.075": "Hele prosjektet i ett rom. Dokumenter, revisjoner, BIM, frister og oversendelser for alle som jobber i prosjektet.",
  "ns.software.076": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Ferdig mappestruktur og revisjonskontroll</span>",
  "ns.software.077": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Oversendelser med kvittering per mottaker</span>",
  "ns.software.078": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Frister med purring på e-post og SMS</span>",
  "ns.software.079": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>BIM i nettleseren, anbudsrom og FDV</span>",
  "ns.software.080": "Les mer om Prosjekthotell <span aria-hidden=\"true\">→</span>",
