  "ns.software.116": "Salgskonsoll",
  "ns.software.117": "Fra første interessent til siste bolig solgt. Interessenter, nyhetsbrev, landingssider, annonser og salgsstatus i én konsoll.",
  "ns.software.118": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Én interessentliste med samtykke og kilde</span>",
  "ns.software.119": "<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg><span>Nyhetsbrev og SMS av ferdige fasebrev</span>",
